    private static bool SampleTinyGlyph(char ch, int gx, int gy)
    {
        if (gx < 0 || gx >= 5 || gy < 0 || gy >= 7) return false;
        string[] rows = ch switch
        {
            'P' => new[] { "11110", "10001", "10001", "11110", "10000", "10000", "10000" },
            'Z' => new[] { "11111", "00001", "00010", "00100", "01000", "10000", "11111" },
            'E' => new[] { "11111", "10000", "10000", "11110", "10000", "10000", "11111" },
            'R' => new[] { "11110", "10001", "10001", "11110", "10100", "10010", "10001" },
            'O' => new[] { "01110", "10001", "10001", "10001", "10001", "10001", "01110" },
            'I' => new[] { "11111", "00100", "00100", "00100", "00100", "00100", "11111" },
            'L' => new[] { "10000", "10000", "10000", "10000", "10000", "10000", "11111" },
            _ => null
        };
        return rows != null && rows[gy][gx] == '1';
    }

    private static void DrawArcText(Image img, int sz, string text, float rInner, float rOuter, float startAng, float endAng, Color col)
    {
        float half = sz * 0.5f;
        int len = text.Length;
        float span = endAng - startAng;
        float stepAng = span / Mathf.Max(1, len);
        int samplesR = 44;
        int samplesA = len * 28;
        for (int ia = 0; ia < samplesA; ia++)
        {
            float fa = ia / (float)samplesA;
            float ang = startAng + fa * span;
            int charIdx = Mathf.Clamp((int)(fa * len), 0, len - 1);
            float localU = (fa * len) - charIdx;
            if (localU < 0.08f || localU > 0.90f) continue;
            int gx = Mathf.Clamp((int)(((localU - 0.08f) / 0.82f) * 5f), 0, 4);
            char ch = text[charIdx];
            if (ch == ' ') continue;

            for (int ir = 0; ir < samplesR; ir++)
            {
                float fr = ir / (float)(samplesR - 1);
                int gy = Mathf.Clamp((int)((1f - fr) * 7f), 0, 6);
                if (!SampleTinyGlyph(ch, gx, gy)) continue;

                float rr = Mathf.Lerp(rInner, rOuter, fr);
                int px = Mathf.Clamp((int)(half + Mathf.Cos(ang) * rr * half), 0, sz - 1);
                int py = Mathf.Clamp((int)(half + Mathf.Sin(ang) * rr * half), 0, sz - 1);
                img.SetPixel(px, py, col);
                if (px + 1 < sz) img.SetPixel(px + 1, py, col);
                if (py + 1 < sz) img.SetPixel(px, py + 1, col);
            }
        }
    }

    public static StandardMaterial3D CreateTireSidewallMaterial(Color compoundColor)
    {
        const int sz = 512;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        float half = sz * 0.5f;
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float dx = (x - half) / half;
                float dy = (y - half) / half;
                float r = Mathf.Sqrt(dx * dx + dy * dy);
                float ang = Mathf.Atan2(dy, dx);
                if (ang < 0f) ang += Mathf.Tau;

                // Realistic deep satin-black sidewall rubber with subtle radial sheen
                float sheen = 0.072f + 0.014f * Mathf.Sin(r * 16f);
                Color col = new Color(sheen, sheen * 1.04f, sheen * 1.12f);

                // Thin accent compound pinstripe arcs bracketing the curved P ZERO / PIRELLI lettering
                if (r > 0.725f && r < 0.755f)
                {
                    bool inBand = (ang > 0.16f && ang < 1.24f) || (ang > 1.90f && ang < 2.98f)
                               || (ang > 3.30f && ang < 4.38f) || (ang > 5.04f && ang < 6.12f);
                    if (inBand) col = compoundColor;
                }
                else if (r > 0.62f && r <= 0.65f)
                {
                    col = new Color(0.12f, 0.14f, 0.17f);
                }
                else if (r <= 0.60f && r > 0.545f)
                {
                    float glint = 0.44f + 0.18f * Mathf.Sin(ang * 2f);
                    col = new Color(glint, glint * 1.04f, glint * 1.12f);
                }
                else if (r <= 0.545f && r > 0.15f)
                {
                    float spoke = Mathf.Abs(Mathf.Sin(ang * 5.0f));
                    float v = spoke < 0.10f ? 0.22f : (spoke < 0.22f ? 0.13f : 0.075f);
                    col = new Color(v, v * 1.05f, v * 1.15f);
                }
                else if (r <= 0.15f)
                {
                    col = r < 0.075f ? new Color(0.88f, 0.92f, 0.98f) : new Color(0.88f, 0.11f, 0.13f);
                }

                img.SetPixel(x, y, col);
            }
        }

        // Bold Photorealistic Curved "P ZERO" and "PIRELLI" Sidewall Branding (just like real 18" F1 tires!)
        DrawArcText(img, sz, "P ZERO",  0.77f, 0.90f, 0.20f, 1.32f, compoundColor);
        DrawArcText(img, sz, "PIRELLI", 0.77f, 0.90f, 1.76f, 2.98f, compoundColor);
        DrawArcText(img, sz, "P ZERO",  0.77f, 0.90f, 3.34f, 4.46f, compoundColor);
        DrawArcText(img, sz, "PIRELLI", 0.77f, 0.90f, 4.90f, 6.12f, compoundColor);

        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.40f,
            Metallic = 0.18f,
            ClearcoatEnabled = true,
            Clearcoat = 0.22f,
            ClearcoatRoughness = 0.42f
        };
    }

    /// <summary>
    /// Procedural dark carbon honeycomb vent/mesh texture for the curved cockpit dash brow & air vents.
    /// </summary>
    public static StandardMaterial3D CreateHoneycombVentMaterial()
    {
        const int sz = 128;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        float[,] hMap = new float[sz, sz];
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                int row = y / 12;
                int rx = (x + (row % 2) * 6) % 12;
                int ry = y % 12;
                float dx = (rx - 6) / 6f;
                float dy = (ry - 6) / 6f;
                float d = Mathf.Sqrt(dx * dx + dy * dy);
                bool cell = d < 0.64f;
                hMap[x, y] = cell ? -0.45f : 0.25f;
                float v = cell ? 0.03f : 0.24f;
                img.SetPixel(x, y, new Color(v, v * 1.04f, v * 1.12f));
            }
        }
        GenerateNormalMapFromHeight(hMap, sz, 4.5f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            NormalEnabled = true,
            NormalTexture = ImageTexture.CreateFromImage(normImg),
            NormalScale = 0.85f,
            Roughness = 0.34f,
            Metallic = 0.45f,
            Uv1Scale = new Vector3(5f, 1.5f, 1f)
        };
    }

    public static StandardMaterial3D CreateMetalMaterial(Color tint, float roughness = 0.22f)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = tint,
            Metallic = 0.90f,
            Roughness = roughness
        };
    }

    public static StandardMaterial3D CreateEmissiveMaterial(Color color, float energy = 1.6f)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = color,
            EmissionEnabled = true,
            Emission = color,
            EmissionEnergyMultiplier = energy,
            Roughness = 0.18f
        };
    }

    public static StandardMaterial3D CreateVertexColorMaterial(float roughness = 0.78f, bool doubleSided = false)
    {
        return new StandardMaterial3D
        {
            VertexColorUseAsAlbedo = true,
            Roughness = roughness,
            Metallic = 0.05f,
            CullMode = doubleSided ? BaseMaterial3D.CullModeEnum.Disabled : BaseMaterial3D.CullModeEnum.Back
        };
    }


    /// <summary>
    /// Procedural 256x256 Organic Leaf-Cluster Foliage PBR Material (Albedo + Normal Map) — eliminates plastic sphere trees!
    /// </summary>
    public static StandardMaterial3D CreateFoliageMaterial(Color baseGreen, int seed)
    {
        const int sz = 256;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(seed);
        float[,] hMap = new float[sz, sz];

        // Fill base canopy shadow
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float d = 0.56f + ((float)rng.NextDouble() - 0.5f) * 0.14f;
                img.SetPixel(x, y, new Color(baseGreen.R * d, baseGreen.G * d, baseGreen.B * d));
                hMap[x, y] = -0.30f;
            }
        }

        // Stamp 2600 overlapping organic leaf dabs with sunlit tips & dark undersides
        for (int i = 0; i < 2600; i++)
        {
            int cx = rng.Next(sz);
            int cy = rng.Next(sz);
            int rx = 3 + rng.Next(5);
            int ry = 2 + rng.Next(4);
            float shade = 0.72f + (float)rng.NextDouble() * 0.62f;
            float warm = (float)rng.NextDouble() * 0.08f;
            Color leafCol = new Color(
                Mathf.Clamp(baseGreen.R * shade + warm, 0f, 1f),
                Mathf.Clamp(baseGreen.G * shade + warm * 0.6f, 0f, 1f),
                Mathf.Clamp(baseGreen.B * shade * 0.85f, 0f, 1f));
            float hVal = (shade - 0.72f) * 0.85f;

            for (int dy = -ry; dy <= ry; dy++)
            {
                for (int dx = -rx; dx <= rx; dx++)
                {
                    if ((dx * dx) / (float)(rx * rx) + (dy * dy) / (float)(ry * ry) <= 1.0f)
                    {
                        int px = (cx + dx + sz) % sz;
                        int py = (cy + dy + sz) % sz;
                        img.SetPixel(px, py, leafCol);
                        hMap[px, py] = hVal;
                    }
                }
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 4.6f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            NormalEnabled = true,
            NormalTexture = ImageTexture.CreateFromImage(normImg),
            NormalScale = 0.85f,
            Roughness = 0.94f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(2.5f, 2.5f, 1.0f)
        };
    }

    public static StandardMaterial3D CreateBarkMaterial()
    {
        const int sz = 128;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(606);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float ridge = Mathf.Sin((x / (float)sz) * Mathf.Tau * 10f + Mathf.Sin(y * 0.08f) * 1.4f) * 0.14f;
                float n = ((float)rng.NextDouble() - 0.5f) * 0.08f;
                hMap[x, y] = ridge + n;
                float v = Mathf.Clamp(0.24f + ridge * 0.5f + n * 0.4f, 0.08f, 0.42f);
                img.SetPixel(x, y, new Color(v * 1.18f, v * 0.82f, v * 0.56f));
            }
        }
        GenerateNormalMapFromHeight(hMap, sz, 5.5f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            NormalEnabled = true,
            NormalTexture = ImageTexture.CreateFromImage(normImg),
            NormalScale = 0.78f,
            Roughness = 0.95f,
            Metallic = 0.0f
        };
    }

    public static StandardMaterial3D CreateCatchFenceMaterial()
    {
        const int sz = 64;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                bool cableH = (y == 16 || y == 48);
                bool wire = ((x + y) % 8 == 0) || ((x - y + 64) % 8 == 0);
                if (cableH) img.SetPixel(x, y, new Color(0.75f, 0.80f, 0.86f, 0.78f));
                else if (wire) img.SetPixel(x, y, new Color(0.58f, 0.64f, 0.72f, 0.42f));
                else img.SetPixel(x, y, new Color(0f, 0f, 0f, 0f));
            }
        }
        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            Roughness = 0.45f,
            Metallic = 0.75f,
            CullMode = BaseMaterial3D.CullModeEnum.Disabled,
            Uv1Scale = new Vector3(1.0f, 1.0f, 1.0f)
        };
    }

    private static void GenerateNormalMapFromHeight(float[,] hMap, int sz, float strength, Image outImg)
    {
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float dx = (hMap[(x + 1) % sz, y] - hMap[(x - 1 + sz) % sz, y]) * strength;
                float dy = (hMap[x, (y + 1) % sz] - hMap[x, (y - 1 + sz) % sz]) * strength;
                Vector3 n = new Vector3(-dx, -dy, 1.0f).Normalized();
                outImg.SetPixel(x, y, new Color(n.X * 0.5f + 0.5f, n.Y * 0.5f + 0.5f, n.Z * 0.5f + 0.5f));
            }
        }
    }
}

