        };
        var garageBayDark = new StandardMaterial3D { AlbedoColor = new Color(0.05f, 0.06f, 0.09f), Roughness = 0.88f };
        var garageGlow = ProceduralMaterialFactory.CreateEmissiveMaterial(new Color(0.95f, 0.97f, 1.0f), 1.4f);
        var fiaRed = new StandardMaterial3D { AlbedoColor = new Color(0.88f, 0.07f, 0.09f), Roughness = 0.34f };
        var whiteTrim = new StandardMaterial3D { AlbedoColor = new Color(0.95f, 0.96f, 0.98f), Roughness = 0.38f };

        // Main 2-Story Paddock & Pit Garage Complex (105m long)
