            Position = new Vector3(4.5f, 9.0f, 0f),
            MaterialOverride = whiteTrim
        });
        pitComplex.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.5f, 0.72f, 105.0f) },
            Position = new Vector3(-1.9f, 4.3f, 0f),
            MaterialOverride = fiaRed
        });
        pitComplex.AddChild(new Label3D
        {
            Text = "APEX GP 24   •   PADDOCK CLUB   •   PIT LANE",
            Position = new Vector3(-2.22f, 4.3f, 0f),
            RotationDegrees = new Vector3(0f, -90f, 0f),
            FontSize = 64,
            PixelSize = 0.0080f,
            Modulate = Colors.White,
            OutlineSize = 0
        });

        // 10 Illuminated F1 Team Garage Bays facing the track!
        Color[] teamStripes =
        {
            new(1.00f, 0.42f, 0.01f), new(0.86f, 0.07f, 0.10f), new(0.08f, 0.16f, 0.48f),
            new(0.00f, 0.80f, 0.72f), new(0.00f, 0.42f, 0.36f), new(0.02f, 0.36f, 0.92f),
            new(0.96f, 0.34f, 0.66f), new(0.92f, 0.94f, 0.97f), new(0.06f, 0.88f, 0.42f),
            new(0.84f, 0.08f, 0.18f)
        };
        for (int g = 0; g < 10; g++)
        {
            float gz = -44.0f + g * 9.8f;
            pitComplex.AddChild(new MeshInstance3D
