                Mesh = new BoxMesh { Size = new Vector3(0.4f, 3.2f, 7.6f) },
                Position = new Vector3(-0.08f, 1.6f, gz),
                MaterialOverride = garageBayDark
            });
            // Interior overhead garage strip light
            pitComplex.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.3f, 0.24f, 6.8f) },
                Position = new Vector3(-0.15f, 3.05f, gz),
                MaterialOverride = garageGlow
            });
            // Team livery fascia stripe above each garage bay
            pitComplex.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.45f, 0.36f, 8.2f) },
                Position = new Vector3(-0.12f, 3.52f, gz),
                MaterialOverride = new StandardMaterial3D { AlbedoColor = teamStripes[g], Roughness = 0.32f }
            });
        }

        // Tall Glass Race Control Tower beside the Start/Finish line!
        pitComplex.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(7.2f, 15.5f, 9.5f) },
            Position = new Vector3(4.2f, 7.75f, 56.5f),
            MaterialOverride = pitConcrete
        });
        pitComplex.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(8.2f, 3.4f, 10.6f) },
            Position = new Vector3(3.6f, 13.8f, 56.5f),
            MaterialOverride = pitGlass
        });
        pitComplex.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(8.6f, 0.55f, 11.0f) },
            Position = new Vector3(3.6f, 15.75f, 56.5f),
            MaterialOverride = fiaRed
        });

        // 2. Dual Tire-Skid Braking Rubber Marks painted onto the Asphalt approaching heavy corners + Glowing FIA Digital Flag Panels!
        var skidSt = new SurfaceTool();
        skidSt.Begin(Mesh.PrimitiveType.Triangles);
        var flagGreenMat = ProceduralMaterialFactory.CreateEmissiveMaterial(new Color(0.05f, 0.96f, 0.40f), 2.4f);
        var panelFrameMat = ProceduralMaterialFactory.CreateMetalMaterial(new Color(0.10f, 0.12f, 0.16f), 0.35f);

        int count = Samples.Count;
        float lastSkidDist = -180f;
        for (int i = 0; i < count; i++)
        {
            float absK = Mathf.Abs(Samples[i].Curvature);
            if (absK > 0.017f && (Samples[i].Distance - lastSkidDist) > 190f)
            {
                lastSkidDist = Samples[i].Distance;
                float outsideSide = Samples[i].Curvature > 0f ? -1f : 1f;

                // Lay dual darkened F1 braking rubber skid ribbons from -115m to -18m before apex!
                for (float d = 115f; d > 18f; d -= 6.0f)
                {
                    TrackSample sa = SampleAtDistance(Samples[i].Distance - d);
                    TrackSample sb = SampleAtDistance(Samples[i].Distance - d + 6.0f);
                    float intensity = Mathf.Sin(((d - 18f) / 97f) * Mathf.Pi) * 0.36f;
                    Color skidCol = new Color(0.04f, 0.045f, 0.055f, intensity);
                    float laneC = outsideSide * (TrackHalfWidth * 0.44f);
                    foreach (float wheelOff in new[] { -0.82f, 0.82f })
                    {
                        Vector3 pA = sa.Center + sa.Right * (laneC + wheelOff) + Vector3.Up * 0.056f;
                        Vector3 pB = sb.Center + sb.Right * (laneC + wheelOff) + Vector3.Up * 0.056f;
                        AddColorQuad(skidSt, pA - sa.Right * 0.24f, pB - sb.Right * 0.24f, pB + sb.Right * 0.24f, pA + sa.Right * 0.24f, skidCol);
                    }
                }

                // Glowing FIA Digital Marshal Flag Panel mounted on the catch-fence at corner entry!
                TrackSample fp = SampleAtDistance(Samples[i].Distance - 45f);
                var panel = new Node3D
                {
                    Position = fp.Center + fp.Right * (outsideSide * (BarrierOffset - 0.15f)) + Vector3.Up * 2.55f,
                    Basis = Basis.LookingAt(fp.Forward, Vector3.Up)
                };
                AddChild(panel);
                panel.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(1.10f, 0.80f, 0.16f) },
                    MaterialOverride = panelFrameMat
                });
                panel.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(0.92f, 0.62f, 0.04f) },
                    Position = new Vector3(0f, 0f, 0.09f),
                    MaterialOverride = flagGreenMat
                });
            }
        }
        skidSt.GenerateNormals();
        AddChild(new MeshInstance3D
        {
            Name = "BrakingSkidMarks",
            Mesh = skidSt.Commit(),
            MaterialOverride = new StandardMaterial3D
            {
                VertexColorUseAsAlbedo = true,
                Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
                Roughness = 0.65f,
                CullMode = BaseMaterial3D.CullModeEnum.Disabled
            }
        });
    }

    private void BuildHorizonMountainsAndClouds()
    {
        // Scenic distant mountain ridge ring around the circuit (adds huge depth & realism!)
        var rng = new Random(909);
        var mtnFarMat = new StandardMaterial3D { AlbedoColor = new Color(0.24f, 0.34f, 0.44f), Roughness = 0.96f };
        var mtnNearMat = new StandardMaterial3D { AlbedoColor = new Color(0.16f, 0.28f, 0.21f), Roughness = 0.94f };
        Vector3 circuitCenter = new Vector3(115f, -2f, -45f);

        // Soft wide rolling hills & distant ridges (natural European GP silhouette instead of sharp cones!)
        for (int i = 0; i < 32; i++)
        {
            float ang = (i / 32f) * Mathf.Tau;
            float dist = 560f + (float)rng.NextDouble() * 140f;
            float h = 34f + (float)rng.NextDouble() * 44f;
            float rx = 125f + (float)rng.NextDouble() * 95f;
            float rz = 90f + (float)rng.NextDouble() * 70f;
            AddChild(new MeshInstance3D
            {
                Mesh = new SphereMesh { Radius = 1.0f, Height = 2.0f, RadialSegments = 14, Rings = 7 },
                Position = circuitCenter + new Vector3(Mathf.Cos(ang) * dist, -8f, Mathf.Sin(ang) * dist),
                Scale = new Vector3(rx, h, rz),
                RotationDegrees = new Vector3(0f, Mathf.RadToDeg(ang), 0f),
                MaterialOverride = (i % 2 == 0) ? mtnFarMat : mtnNearMat
            });
        }

        // Soft volumetric cloud puffs drifting high above the horizon
        var cloudMat = new StandardMaterial3D
        {
            AlbedoColor = new Color(0.96f, 0.98f, 1.0f, 0.72f),
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            Roughness = 1.0f
        };
        for (int c = 0; c < 18; c++)
        {
            float ang = (c / 18f) * Mathf.Tau + 0.12f;
            float dist = 420f + (float)rng.NextDouble() * 220f;
            float cy = 115f + (float)rng.NextDouble() * 55f;
            AddChild(new MeshInstance3D
            {
                Mesh = new SphereMesh { Radius = 28f + (float)rng.NextDouble() * 22f, Height = 16f, RadialSegments = 10, Rings = 5 },
                Position = circuitCenter + new Vector3(Mathf.Cos(ang) * dist, cy, Mathf.Sin(ang) * dist),
                Scale = new Vector3(2.4f, 0.55f, 1.2f),
                MaterialOverride = cloudMat
            });
        }
    }


    private void AddInstancedBatch(string name, Mesh mesh, Material mat, List<(Transform3D xform, Color col)> items)
    {
        if (items.Count == 0) return;
        var mm = new MultiMesh
        {
            TransformFormat = MultiMesh.TransformFormatEnum.Transform3D,
            UseColors = true,
            Mesh = mesh,
            InstanceCount = items.Count
        };
        for (int i = 0; i < items.Count; i++)
        {
            mm.SetInstanceTransform(i, items[i].xform);
            mm.SetInstanceColor(i, items[i].col);
        }
        AddChild(new MultiMeshInstance3D
        {
            Name = name,
            Multimesh = mm,
            MaterialOverride = mat,
            CastShadow = GeometryInstance3D.ShadowCastingSetting.Off
        });
    }

    private static void AddUvQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector2 uvA, Vector2 uvB, Vector2 uvC, Vector2 uvD)
    {
        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvB); st.AddVertex(b);
        st.SetUV(uvC); st.AddVertex(c);

        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvC); st.AddVertex(c);
        st.SetUV(uvD); st.AddVertex(d);
    }

    private static void AddColorQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Color col)
    {
        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(b);
        st.SetColor(col); st.AddVertex(c);

        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(c);
        st.SetColor(col); st.AddVertex(d);
    }
}

