    private Vector3 _prevPos;
    private Basis _prevBasis = Basis.Identity;
    private Vector3 _currPos;
    private Basis _currBasis = Basis.Identity;

    public float EngineRpm => _engineRpm;

    public int Gear
    {
        get
        {
            if (SpeedKmh < 82f) return 1;
            if (SpeedKmh < 126f) return 2;
            if (SpeedKmh < 168f) return 3;
            if (SpeedKmh < 208f) return 4;
            if (SpeedKmh < 248f) return 5;
            if (SpeedKmh < 286f) return 6;
            if (SpeedKmh < 320f) return 7;
            return 8;
        }
    }

    public float RpmNormalized => Mathf.Clamp((_engineRpm - 5500f) / 8500f, 0f, 1f);

    public void Initialize(TrackBuilder3D track)
    {
        _track = track;
        BuildCar3D();
        ResetToGrid(12.0f, -2.8f);
    }

    public void SetCameraMode(bool cockpit, bool save = false)
    {
        IsCockpitCamera = cockpit;
        if (_cockpitCam != null) _cockpitCam.Current = IsCockpitCamera;
        if (_tCam != null) _tCam.Current = !IsCockpitCamera;
        if (save)
        {
            GameSettings.CockpitCamera = IsCockpitCamera;
            GameSettings.Save();
        }
    }

    public void ToggleCamera()
    {
        SetCameraMode(!IsCockpitCamera, true);
    }

    public void SetLivery(int index, bool save = false)
    {
        LiveryIndex = ((index % Liveries.Length) + Liveries.Length) % Liveries.Length;
        var liv = CurrentLivery;
        if (_primaryPaintMat != null) _primaryPaintMat.AlbedoColor = liv.Primary;
        if (_secondaryPaintMat != null) _secondaryPaintMat.AlbedoColor = liv.Secondary;
        if (_noseTeamLabel != null)
        {
            _noseTeamLabel.Text = liv.Code;
            _noseTeamLabel.Modulate = liv.Secondary;
        }
        if (_haloSponsorLabel != null)
        {
            _haloSponsorLabel.Text = liv.HaloSponsor;
        }
        _steeringWheel?.UpdateColors(liv.Glove);
        _driverArms?.UpdateColors(liv.Secondary, liv.Primary, liv.Glove);
        if (save)
        {
            GameSettings.LiveryIndex = LiveryIndex;
            GameSettings.Save();
        }
    }

    public void CycleLivery()
    {
        SetLivery(LiveryIndex + 1, true);
    }

    public void ResetToGrid(float startDist, float startLane)
    {
        TrackDistance = startDist;
        TotalDistance = startDist;
        LateralOffset = startLane;
        HeadingOffset = 0f;
        SpeedKmh = 0f;
        SteerAngle = 0f;
        BrakePressure = 0f;
        ErsCharge = 100f;
        ErsEnabled = false;
        CurrentLap = 1;
        RaceFinished = false;
        QualiLapCompleted = false;
        CurrentLapTime = 0f;
        _smoothLatG = 0f;
        _smoothLongG = 0f;
        _smoothBrakeHeat = 0f;
        _smoothTireHeat = 0.38f;
        _engineRpm = 4200f;
        _impactLatVel = 0f;
        ComputePose(out _currPos, out _currBasis);
        _prevPos = _currPos;
        _prevBasis = _currBasis;
        Position = _currPos;
        Basis = _currBasis;
        SyncDriverArmsIK();
    }

    public void SyncDriverArmsIK()
    {
        if (_driverArms != null && _steeringWheel != null)
        {
            _driverArms.UpdateIK(
                _steeringWheel.GetLeftWristLocalInCar(),
                _steeringWheel.GetRightWristLocalInCar(),
                SteerAngle);
        }
    }

