    private bool _analogMode = false;
    private int _sensIndex = 2; // 0=Suave(0.85), 1=Media(1.05), 2=Ágil(1.25), 3=Pro(1.50)
    private static readonly float[] SensValues = { 0.85f, 1.05f, 1.25f, 1.50f };
    private static readonly string[] SensNames = { "SUAVE (85%)", "MEDIA (105%)", "ÁGIL (125%)", "PRO (150%)" };

    private int _steerPointerId = -1;
    private readonly HashSet<int> _brakePointers = new();
