    public void Initialize(PlayerCar3D car, MainRaceController raceCtrl)
    {
        _car = car;
        _raceCtrl = raceCtrl;

        // Restore persisted steering mode & sensitivity from disk!
        _analogMode = GameSettings.AnalogSteering;
        _sensIndex = Mathf.Clamp(GameSettings.SensitivityIndex, 0, SensValues.Length - 1);
        _car.SteerSensitivity = SensValues[_sensIndex];

        BuildUi();
        ApplySteeringModeVisuals();
        RefreshPauseMenuVisuals();
    }

    private void BuildUi()
    {
        var root = new Control();
        root.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        root.MouseFilter = Control.MouseFilterEnum.Ignore;
