        });
    }

    private void ApplySteeringModeVisuals()
    {
        if (_btnLeft != null) _btnLeft.Visible = !_analogMode;
        if (_btnRight != null) _btnRight.Visible = !_analogMode;
        if (_analogTrack != null) _analogTrack.Visible = _analogMode;
    }

    private void RefreshPauseMenuVisuals()
    {
        if (_modeBtn == null) return;

        // Controls
        _modeBtn.Text = _analogMode ? "DIRECCIÓN:  DESLIZANTE ANALÓGICA" : "DIRECCIÓN:  BOTONES < >";
        ApplySettingAccent(_modeBtn, _analogMode ? new Color(0.0f, 0.88f, 1.0f) : new Color(0.28f, 0.68f, 1.0f), new Color(0.09f, 0.14f, 0.23f));

        _sensBtn.Text = $"SENSIBILIDAD:  {SensNames[_sensIndex]}";
        Color sensCol = _sensIndex >= 3 ? new Color(1.0f, 0.55f, 0.14f) : new Color(0.0f, 0.88f, 1.0f);
        ApplySettingAccent(_sensBtn, sensCol, new Color(0.09f, 0.14f, 0.23f));

        // Assists & Audio
        bool lineOn = _raceCtrl.IsRacingLineOn;
        _lineBtn.Text = lineOn ? "TRAZADA 3D:  ACTIVADA (ON)" : "TRAZADA 3D:  APAGADA (OFF)";
        ApplySettingAccent(_lineBtn,
            lineOn ? new Color(0.10f, 0.92f, 0.48f) : new Color(0.55f, 0.30f, 0.34f),
            lineOn ? new Color(0.08f, 0.18f, 0.16f) : new Color(0.11f, 0.11f, 0.16f));

        bool sndOn = _raceCtrl.IsSoundOn;
        _soundBtn.Text = sndOn ? "SONIDO MOTOR V6:  ON" : "SONIDO MOTOR V6:  MUTE";
        ApplySettingAccent(_soundBtn,
            sndOn ? new Color(0.10f, 0.92f, 0.48f) : new Color(0.55f, 0.30f, 0.34f),
            sndOn ? new Color(0.08f, 0.18f, 0.16f) : new Color(0.11f, 0.11f, 0.16f));

        // Team Livery (shows the team's REAL primary paint color on the left accent bar!)
        var liv = _car.CurrentLivery;
        _teamBtn.Text = $"EQUIPO:  {liv.Name}";
        ApplySettingAccent(_teamBtn, liv.Primary, new Color(0.10f, 0.13f, 0.21f));

        // Weather / Time of Day
        _timeBtn.Text = $"CLIMA:  {_raceCtrl.CurrentTimeLabel}";
        Color timeCol = _raceCtrl.CurrentTimePreset switch
        {
            TimeOfDayPreset.Sunset => new Color(1.0f, 0.52f, 0.18f),
            TimeOfDayPreset.Night => new Color(0.45f, 0.52f, 1.0f),
            _ => new Color(0.28f, 0.80f, 1.0f)
        };
        ApplySettingAccent(_timeBtn, timeCol, new Color(0.09f, 0.14f, 0.23f));

        // Graphics & Camera
        bool hiQ = _raceCtrl.IsHighQuality;
        _qualBtn.Text = $"GRÁFICOS:  {_raceCtrl.CurrentQualityLabel}";
        ApplySettingAccent(_qualBtn, hiQ ? new Color(0.64f, 0.46f, 1.0f) : new Color(0.45f, 0.62f, 0.78f), new Color(0.10f, 0.13f, 0.22f));

        _camMenuBtn.Text = _car.IsCockpitCamera ? "CÁMARA:  COCKPIT (PILOTO)" : "CÁMARA:  T-CAM (SUPERIOR)";
        ApplySettingAccent(_camMenuBtn, new Color(0.0f, 0.86f, 1.0f), new Color(0.09f, 0.14f, 0.23f));
    }

    private void TriggerSaveFlash()
    {
        _saveFlashTimer = 1.6f;
        if (_saveStatusLbl != null)
        {
            _saveStatusLbl.Text = "✓  ¡AJUSTE GUARDADO EN TU DISPOSITIVO!";
            _saveStatusLbl.AddThemeColorOverride("font_color", new Color(0.25f, 1.0f, 0.56f));
        }
    }

    private void TogglePauseMenu()
    {
        bool paused = !_pauseBackdrop.Visible;
        _pauseBackdrop.Visible = paused;
        _raceCtrl.IsPaused = paused;
        if (paused)
        {
            ClearTouches();
            RefreshPauseMenuVisuals();
        }
    }

    private void ClearTouches()
    {
        _steerPointerId = -1;
        _brakePointers.Clear();
        _gasPointers.Clear();
        _car.InputLeft = false;
        _car.InputRight = false;
        _car.AnalogSteerTarget = null;
        _car.InputBrake = false;
        _car.InputGas = false;
    }

    private Vector2 ToCanvasCoords(Vector2 screenPos)
    {
        return Transform.AffineInverse() * screenPos;
    }

    public override void _Input(InputEvent @event)
    {
        if (_car == null || _pauseBackdrop.Visible || _finishOverlay.Visible) return;

        if (@event is InputEventScreenTouch touch)
        {
            Vector2 pos = ToCanvasCoords(touch.Position);
            if (touch.Pressed) HandlePointerDown(touch.Index, pos);
            else HandlePointerUp(touch.Index);
        }
        else if (@event is InputEventScreenDrag drag)
        {
            Vector2 pos = ToCanvasCoords(drag.Position);
            HandlePointerMove(drag.Index, pos);
        }
    }

    private void HandlePointerDown(int id, Vector2 pos)
    {
        Rect2 steerRect = _steerZone.GetGlobalRect().Grow(28f);
        Rect2 ersRect = _btnErs.GetGlobalRect().Grow(16f);
        Rect2 brakeRect = _btnBrake.GetGlobalRect().Grow(18f);
        Rect2 gasRect = _btnGas.GetGlobalRect().Grow(20f);

        if (steerRect.HasPoint(pos))
        {
            _steerPointerId = id;
            ApplySteerFromPoint(pos);
            return;
        }
        if (ersRect.HasPoint(pos))
        {
            _car.ErsEnabled = !_car.ErsEnabled;
            return;
        }
        if (brakeRect.HasPoint(pos))
        {
            _brakePointers.Add(id);
            SyncPedals();
            return;
        }
        if (gasRect.HasPoint(pos))
        {
            _gasPointers.Add(id);
            SyncPedals();
        }
    }

    private void HandlePointerMove(int id, Vector2 pos)
    {
        if (id == _steerPointerId)
        {
            ApplySteerFromPoint(pos);
            return;
        }

        if (_brakePointers.Contains(id) || _gasPointers.Contains(id))
        {
            Rect2 brakeRect = _btnBrake.GetGlobalRect().Grow(26f);
            Rect2 gasRect = _btnGas.GetGlobalRect().Grow(26f);
            if (_brakePointers.Contains(id) && !brakeRect.HasPoint(pos) && gasRect.HasPoint(pos))
            {
                _brakePointers.Remove(id);
                _gasPointers.Add(id);
                SyncPedals();
            }
            else if (_gasPointers.Contains(id) && !gasRect.HasPoint(pos) && brakeRect.HasPoint(pos))
            {
                _gasPointers.Remove(id);
                _brakePointers.Add(id);
                SyncPedals();
            }
        }
    }

    private void HandlePointerUp(int id)
    {
        if (id == _steerPointerId)
        {
            _steerPointerId = -1;
            _car.InputLeft = false;
            _car.InputRight = false;
            _car.AnalogSteerTarget = null;
        }
        if (_brakePointers.Remove(id) || _gasPointers.Remove(id))
        {
            SyncPedals();
        }
    }

    private void ApplySteerFromPoint(Vector2 pos)
    {
        Rect2 r = _steerZone.GetGlobalRect();
        float midX = r.Position.X + r.Size.X * 0.5f;
        if (_analogMode)
        {
            float halfTravel = Mathf.Max(28f, r.Size.X * 0.42f);
            float norm = Mathf.Clamp((pos.X - midX) / halfTravel, -1f, 1f);
            float val = Mathf.Abs(norm) < 0.04f ? 0f : norm;
            _car.AnalogSteerTarget = val;
            _car.InputLeft = val < -0.04f;
            _car.InputRight = val > 0.04f;
        }
        else
        {
            _car.AnalogSteerTarget = null;
            bool isRight = pos.X >= midX;
            _car.InputLeft = !isRight;
            _car.InputRight = isRight;
        }
    }

    private void SyncPedals()
    {
        _car.InputBrake = _brakePointers.Count > 0;
        _car.InputGas = _gasPointers.Count > 0;
    }

    public override void _Process(double delta)
    {
        if (_car == null) return;

        if (_saveFlashTimer > 0f)
        {
            _saveFlashTimer = Mathf.Max(0f, _saveFlashTimer - (float)delta);
            if (_saveFlashTimer <= 0f && _saveStatusLbl != null)
            {
                _saveStatusLbl.Text = "✓  TUS AJUSTES SE GUARDAN AUTOMÁTICAMENTE";
                _saveStatusLbl.AddThemeColorOverride("font_color", new Color(0.32f, 0.92f, 0.62f));
            }
        }

        _skipQualiBtn.Visible = _raceCtrl.IsQualifying;
        if (_raceCtrl.IsQualifying)
        {
            _posLbl.Text = $"QUALI • P{_car.CurrentPosition}";
            _lapLbl.Text = $"1 VUELTA • {_car.CurrentLapTime:00.000}s";
            _lbLines.Text = $"POLE {_raceCtrl.PoleReferenceTime:00.000}s\nVTA  {_car.CurrentLapTime:00.000}s\nPROY P{_car.CurrentPosition} / 20";
        }
        else
        {
            _posLbl.Text = $"P{_car.CurrentPosition} / 20";
            string bestStr = _car.BestLapTime < 900f ? $"  •  B {_car.BestLapTime:00.0}" : "";
            _lapLbl.Text = $"VTA {Mathf.Min(_car.CurrentLap, PlayerCar3D.TotalLaps)}/{PlayerCar3D.TotalLaps}  •  {_car.CurrentLapTime:00.00}{bestStr}";
            _lbLines.Text = _raceCtrl.BuildMiniLeaderboardText();
        }

        string hint = _minimap?.UpcomingCornerHint ?? "";
        _cornerCueCard.Visible = _raceCtrl.RaceStarted && !_car.RaceFinished && hint.Length > 0;
        if (_cornerCueCard.Visible) _cornerCueLbl.Text = hint;

        if (_car.RaceFinished && !_finishOverlay.Visible)
        {
            ClearTouches();
            string bestFin = _car.BestLapTime < 900f ? $"{_car.BestLapTime:00.000}s" : "--";
            _finishDetailsLbl.Text = $"POSICIÓN FINAL: P{_car.CurrentPosition} / 20\nMEJOR VUELTA: {bestFin}";
            _finishOverlay.Visible = true;
        }

        if (!_raceCtrl.RaceStarted)
        {
            _startLightsCard.Visible = true;
            int lit = _raceCtrl.StartLightsLitCount;
            for (int i = 0; i < 5; i++)
            {
                _startLightDots[i].Color = i < lit ? new Color(1.0f, 0.08f, 0.14f) : new Color(0.18f, 0.06f, 0.07f);
            }
        }
        else
        {
            _startLightsCard.Visible = false;
        }

        _speedLbl.Text = $"{(int)_car.SpeedKmh} KM/H";
        _gearLbl.Text = $"G{_car.Gear}";
        _ersLbl.Text = _car.ErsEnabled ? $"ERS BOOST {(int)_car.ErsCharge}%" : $"ERS {(int)_car.ErsCharge}%";
        _offTrackBanner.Visible = _raceCtrl.RaceStarted && _car.IsOffTrack && _car.SpeedKmh > 18f;
        _slipBanner.Visible = _raceCtrl.RaceStarted && _car.InSlipstream;

        float rpm = _car.RpmNormalized;
        _rpmFill.Size = new Vector2(Mathf.Max(8f, 292f * rpm), 11f);
        _rpmFill.Color = rpm > 0.85f ? new Color(0.20f, 0.55f, 1.0f) : (rpm > 0.58f ? new Color(1.0f, 0.16f, 0.20f) : new Color(0.0f, 0.90f, 0.45f));

        // Live Steering Feedback
        _leftStyle.BgColor = _car.InputLeft ? new Color(0.10f, 0.44f, 0.76f, 0.95f) : new Color(0.08f, 0.14f, 0.25f, 0.80f);
        _rightStyle.BgColor = _car.InputRight ? new Color(0.10f, 0.44f, 0.76f, 0.95f) : new Color(0.08f, 0.14f, 0.25f, 0.80f);

        float ang = Mathf.Clamp(_car.SteerAngle, -1f, 1f);
        float halfBar = 220f;
        float wBar = Mathf.Abs(ang) * halfBar;
        _steerBarFill.Position = new Vector2(ang >= 0f ? 230f : (230f - wBar), 188f);
        _steerBarFill.Size = new Vector2(wBar, 14f);
        if (_analogMode)
        {
            _analogKnob.Position = new Vector2(180f + ang * 168f, 20f);
        }

        // Pedal Visual Feedback
        _gasStyle.BgColor = _car.InputGas ? new Color(0.08f, 0.68f, 0.29f, 0.96f) : new Color(0.07f, 0.38f, 0.19f, 0.86f);
        _brakeStyle.BgColor = _car.InputBrake ? new Color(0.78f, 0.12f, 0.14f, 0.96f) : new Color(0.46f, 0.08f, 0.10f, 0.86f);
        float bh = _car.BrakePressure * 182f;
        _brakeBarFill.Position = new Vector2(4f, 186f - bh);
        _brakeBarFill.Size = new Vector2(162f, bh);
        _ersStyle.BgColor = _car.ErsEnabled ? new Color(0.0f, 0.70f, 0.95f, 0.96f) : new Color(0.06f, 0.25f, 0.46f, 0.86f);
    }

    private static Button CreateSettingButton(Vector2 pos, Vector2 size, int fontSize)
    {
        var b = new Button
        {
            Position = pos,
            Size = size,
            FocusMode = Control.FocusModeEnum.None,
            Alignment = HorizontalAlignment.Left
        };
        b.AddThemeFontSizeOverride("font_size", fontSize);
        b.AddThemeColorOverride("font_color", Colors.White);
        b.AddThemeColorOverride("font_hover_color", Colors.White);
        b.AddThemeColorOverride("font_pressed_color", new Color(0.85f, 0.96f, 1.0f));
        return b;
    }

    private static void ApplySettingAccent(Button b, Color accent, Color bg)
    {
        var norm = new StyleBoxFlat
        {
            BgColor = bg,
            BorderColor = accent,
            BorderWidthLeft = 7, BorderWidthRight = 1, BorderWidthTop = 1, BorderWidthBottom = 1,
            CornerRadiusTopLeft = 10, CornerRadiusTopRight = 10, CornerRadiusBottomLeft = 10, CornerRadiusBottomRight = 10,
            ContentMarginLeft = 18, ContentMarginRight = 14
        };
        var hover = (StyleBoxFlat)norm.Duplicate();
        hover.BgColor = bg.Lightened(0.12f);
        var pressed = (StyleBoxFlat)norm.Duplicate();
        pressed.BgColor = bg.Lightened(0.22f);

        b.AddThemeStyleboxOverride("normal", norm);
        b.AddThemeStyleboxOverride("hover", hover);
        b.AddThemeStyleboxOverride("pressed", pressed);
        b.AddThemeStyleboxOverride("focus", new StyleBoxEmpty());
    }

    private static Button CreateStyledButton(string text, Vector2 pos, Vector2 size, int fontSize, Color bg, Color border, int borderW)
    {
        var b = new Button { Text = text, Position = pos, Size = size, FocusMode = Control.FocusModeEnum.None };
        ApplySolidButtonTheme(b, fontSize, bg, border, borderW);
        return b;
    }

    private static Button CreateAnchoredStyledButton(Control parent, float al, float at, float ar, float ab, float ol, float ot, float orr, float ob, string text, int fontSize, Color bg, Color border)
    {
        var b = new Button
        {
            Text = text,
            AnchorLeft = al, AnchorTop = at, AnchorRight = ar, AnchorBottom = ab,
            OffsetLeft = ol, OffsetTop = ot, OffsetRight = orr, OffsetBottom = ob,
            FocusMode = Control.FocusModeEnum.None
        };
        ApplySolidButtonTheme(b, fontSize, bg, border, 2);
        parent.AddChild(b);
        return b;
    }

    private static void ApplySolidButtonTheme(Button b, int fontSize, Color bg, Color border, int borderW)
    {
        b.AddThemeFontSizeOverride("font_size", fontSize);
        b.AddThemeColorOverride("font_color", Colors.White);
        b.AddThemeColorOverride("font_hover_color", Colors.White);
        b.AddThemeColorOverride("font_pressed_color", Colors.White);

        var norm = new StyleBoxFlat
        {
            BgColor = bg,
            BorderColor = border,
            BorderWidthLeft = borderW, BorderWidthRight = borderW, BorderWidthTop = borderW, BorderWidthBottom = borderW,
            CornerRadiusTopLeft = 12, CornerRadiusTopRight = 12, CornerRadiusBottomLeft = 12, CornerRadiusBottomRight = 12
        };
        var hover = (StyleBoxFlat)norm.Duplicate();
        hover.BgColor = bg.Lightened(0.14f);
        var pressed = (StyleBoxFlat)norm.Duplicate();
        pressed.BgColor = bg.Lightened(0.24f);

        b.AddThemeStyleboxOverride("normal", norm);
        b.AddThemeStyleboxOverride("hover", hover);
        b.AddThemeStyleboxOverride("pressed", pressed);
        b.AddThemeStyleboxOverride("focus", new StyleBoxEmpty());
    }

    private static Panel CreateCard(Vector2 pos, Vector2 size, Color bg, Color border)
    {
        var p = new Panel { Position = pos, Size = size, MouseFilter = Control.MouseFilterEnum.Ignore };
        p.AddThemeStyleboxOverride("panel", MakeStyle(bg, border));
        return p;
    }

    private static Panel CreateAnchoredCard(Control parent, float al, float at, float ar, float ab, float ol, float ot, float orr, float ob, Color bg, Color border)
    {
        var p = new Panel
        {
            AnchorLeft = al, AnchorTop = at, AnchorRight = ar, AnchorBottom = ab,
            OffsetLeft = ol, OffsetTop = ot, OffsetRight = orr, OffsetBottom = ob,
            MouseFilter = Control.MouseFilterEnum.Ignore
        };
        p.AddThemeStyleboxOverride("panel", MakeStyle(bg, border));
        parent.AddChild(p);
        return p;
    }

    private static (Panel panel, StyleBoxFlat style) CreateStyledChildPad(Control parent, Vector2 pos, Vector2 size, string text, int fontSize, Color bg, Color border)
    {
        var style = MakeStyle(bg, border);
        var p = new Panel { Position = pos, Size = size, MouseFilter = Control.MouseFilterEnum.Ignore };
        p.AddThemeStyleboxOverride("panel", style);
        var lbl = CreateLabel(text, fontSize, Colors.White);
        lbl.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        lbl.HorizontalAlignment = HorizontalAlignment.Center;
        lbl.VerticalAlignment = VerticalAlignment.Center;
        p.AddChild(lbl);
        parent.AddChild(p);
        return (p, style);
    }

    private static (Panel panel, StyleBoxFlat style) CreateAnchoredControlPad(Control parent, float al, float at, float ar, float ab, float ol, float ot, float orr, float ob, string text, int fontSize, Color bg, Color border)
    {
        var style = MakeStyle(bg, border);
        var p = new Panel
        {
            AnchorLeft = al, AnchorTop = at, AnchorRight = ar, AnchorBottom = ab,
            OffsetLeft = ol, OffsetTop = ot, OffsetRight = orr, OffsetBottom = ob,
            MouseFilter = Control.MouseFilterEnum.Ignore
        };
        p.AddThemeStyleboxOverride("panel", style);
        var lbl = CreateLabel(text, fontSize, Colors.White);
        lbl.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        lbl.HorizontalAlignment = HorizontalAlignment.Center;
        lbl.VerticalAlignment = VerticalAlignment.Center;
        p.AddChild(lbl);
        parent.AddChild(p);
        return (p, style);
    }

    private static StyleBoxFlat MakeStyle(Color bg, Color border)
    {
        return new StyleBoxFlat
        {
            BgColor = bg,
            BorderColor = border,
            BorderWidthLeft = 2, BorderWidthRight = 2, BorderWidthTop = 2, BorderWidthBottom = 2,
            CornerRadiusTopLeft = 14, CornerRadiusTopRight = 14, CornerRadiusBottomLeft = 14, CornerRadiusBottomRight = 14
        };
    }

    private static Label CreateLabel(string text, int fontSize, Color color)
    {
        var lbl = new Label { Text = text, MouseFilter = Control.MouseFilterEnum.Ignore };
        lbl.AddThemeFontSizeOverride("font_size", fontSize);
        lbl.AddThemeColorOverride("font_color", color);
        return lbl;
    }
}

