    public void StartQualifying()
    {
        IsQualifying = true;
        _player.IsQualifying = true;
        _startCountdown = 2.0f;
        _raceTime = 0f;
        PoleReferenceTime = Mathf.Max(14.5f, _track.TotalLength / 76.5f);

        _player.ResetToGrid(4.0f, 0f);
        _player.CurrentPosition = 1;
        for (int i = 0; i < _rivals.Count; i++)
        {
            _rivals[i].Visible = false;
        }
    }

    public void SkipQualifyingToRace()
    {
        QualifiedGridSlot = 16;
        StartRaceFromGrid(QualifiedGridSlot);
    }

    public void StartRaceFromGrid(int playerSlot)
    {
        IsQualifying = false;
        _player.IsQualifying = false;
        QualifiedGridSlot = Mathf.Clamp(playerSlot, 1, 20);
        _startCountdown = 3.4f;
        _raceTime = 0f;

        const float gridStep = 10.5f;
        int rivalIdx = 0;
        for (int pos = 1; pos <= 20; pos++)
        {
            float dist = 12f + (20 - pos) * gridStep;
            float lane = (pos % 2 == 1) ? -2.75f : 2.75f;

            if (pos == QualifiedGridSlot)
            {
                _player.ResetToGrid(dist, lane);
                _player.CurrentPosition = pos;
            }
            else if (rivalIdx < _rivals.Count)
            {
                _rivals[rivalIdx].Visible = true;
                _rivals[rivalIdx].ResetToGrid(dist, lane);
                rivalIdx++;
            }
        }
    }

    public void RestartRace()
    {
        if (IsQualifying) StartQualifying();
        else StartRaceFromGrid(QualifiedGridSlot);
    }

    public override void _PhysicsProcess(double delta)
    {
        if (IsPaused) return;
        float dt = (float)delta;

        if (_startCountdown > 0f)
        {
            _startCountdown = Mathf.Max(0f, _startCountdown - dt);
        }
        else
        {
            _raceTime += dt;
        }

        bool started = RaceStarted;
        if (IsQualifying)
        {
            _player.StepPhysics(dt, started, null, _audio);
            float prog = Mathf.Clamp(_player.TrackDistance / Mathf.Max(1f, _track.TotalLength), 0.03f, 1.0f);
            float projectedLap = _player.CurrentLapTime / prog;
            int projPos = Mathf.Clamp(1 + Mathf.FloorToInt(Mathf.Max(0f, projectedLap - PoleReferenceTime) * 4.5f), 1, 20);
            _player.CurrentPosition = _player.CurrentLapTime < 0.25f ? 1 : projPos;

            if (_player.QualiLapCompleted)
            {
                int slot = Mathf.Clamp(1 + Mathf.FloorToInt(Mathf.Max(0f, _player.LastQualiTime - PoleReferenceTime) * 4.5f), 1, 20);
                StartRaceFromGrid(slot);
            }
            return;
        }

        for (int i = 0; i < _rivals.Count; i++)
        {
            _rivals[i].StepPhysics(dt, _raceTime, _player, started);
        }

        _player.StepPhysics(dt, started, _rivals, _audio);

        int ahead = 0;
        for (int i = 0; i < _rivals.Count; i++)
        {
            if (_rivals[i].TotalDistance > _player.TotalDistance) ahead++;
        }
        _player.CurrentPosition = ahead + 1;
    }

    public override void _Process(double delta)
    {
        if (IsPaused) return;
        // Silky physics-to-display interpolation for buttery 60/90/120Hz motion!
        float alpha = Mathf.Clamp((float)Engine.GetPhysicsInterpolationFraction(), 0f, 1f);
        _player.ApplyInterpolatedPose(alpha);
        if (!IsQualifying)
        {
            for (int i = 0; i < _rivals.Count; i++)
            {
                _rivals[i].ApplyInterpolatedPose(alpha);
            }
        }
    }

    public string BuildMiniLeaderboardText()
    {
        _standings.Clear();
        _standings.Add(("TÚ", _player.TotalDistance, true));
        for (int i = 0; i < _rivals.Count; i++)
        {
            _standings.Add((_rivals[i].Spec.Code, _rivals[i].TotalDistance, false));
        }
        _standings.Sort((a, b) => b.dist.CompareTo(a.dist));

        int pIdx = _standings.FindIndex(x => x.isPlayer);
        int start = Mathf.Clamp(pIdx - 1, 0, Mathf.Max(0, _standings.Count - 3));
        float refDist = _standings[start].dist;

        _lbBuilder.Clear();
        for (int i = start; i < Mathf.Min(_standings.Count, start + 3); i++)
        {
            var e = _standings[i];
            float gapSec = (refDist - e.dist) / 62f;
            string gapStr = i == start ? "LÍDER" : $"+{gapSec:0.00}s";
            string prefix = e.isPlayer ? ">" : " ";
            _lbBuilder.Append($"{prefix}P{i + 1,-2} {e.code,-4} {gapStr}");
            if (i < start + 2) _lbBuilder.Append('\n');
        }
        return _lbBuilder.ToString();
    }

    public bool ToggleRacingLine()
    {
        _racingLineOn = !_racingLineOn;
        _track?.SetRacingLineVisible(_racingLineOn);
        GameSettings.RacingLineOn = _racingLineOn;
        GameSettings.Save();
        return _racingLineOn;
    }

    public bool ToggleSound()
    {
        _audio.Enabled = !_audio.Enabled;
        GameSettings.SoundOn = _audio.Enabled;
        GameSettings.Save();
        return _audio.Enabled;
    }

    public void CycleTimeOfDay()
    {
        _timePreset = (TimeOfDayPreset)(((int)_timePreset + 1) % 3);
        ApplyTimeOfDay(_timePreset);
        GameSettings.TimeOfDayIndex = (int)_timePreset;
        GameSettings.Save();
    }

    public void ToggleQuality()
    {
        _highQuality = !_highQuality;
        ApplyQualitySettings();
        GameSettings.HighQuality = _highQuality;
        GameSettings.Save();
    }

    private void ApplyQualitySettings()
    {
        if (_sunLight != null) _sunLight.ShadowEnabled = _highQuality;
        Viewport vp = GetViewport();
        if (vp != null) vp.Msaa3D = _highQuality ? Viewport.Msaa.Msaa4X : Viewport.Msaa.Msaa2X;
    }

    private void SetupEnvironmentAndSun()
    {
        _worldEnv = new WorldEnvironment { Environment = new Godot.Environment() };
        AddChild(_worldEnv);

        _sunLight = new DirectionalLight3D
        {
            ShadowEnabled = true,
            DirectionalShadowMode = DirectionalLight3D.ShadowMode.Parallel4Splits,
            DirectionalShadowMaxDistance = 230f,
            ShadowBias = 0.04f,
            ShadowNormalBias = 1.2f
        };
        AddChild(_sunLight);

        // Soft sky-bounce rim fill light (no shadow cost!) gives carbon fiber, gloves & shaded panels rich 3D depth!
        AddChild(new DirectionalLight3D
        {
            LightColor = new Color(0.68f, 0.82f, 1.0f),
            LightEnergy = 0.30f,
            ShadowEnabled = false,
            RotationDegrees = new Vector3(-25f, 145f, 0f)
        });
    }

    private void ApplyTimeOfDay(TimeOfDayPreset preset)
    {
        var sky = new Sky();
        Texture2D hdri = AssetLoader3D.TryLoadTexture("Sky HDRI", "res://assets/textures/sky.hdr", "res://assets/textures/sky.exr");

        bool useCustomHdri = hdri != null && preset == TimeOfDayPreset.Day;
        if (useCustomHdri)
        {
            sky.SkyMaterial = new PanoramaSkyMaterial { Panorama = hdri };
        }
        else if (preset == TimeOfDayPreset.Sunset)
        {
            sky.SkyMaterial = new ProceduralSkyMaterial
            {
                SkyTopColor = new Color(0.11f, 0.16f, 0.36f),
                SkyHorizonColor = new Color(0.96f, 0.48f, 0.22f),
                GroundBottomColor = new Color(0.10f, 0.08f, 0.09f),
                GroundHorizonColor = new Color(0.68f, 0.38f, 0.24f),
                SunAngleMax = 28f,
                SunCurve = 0.06f
            };
        }
        else if (preset == TimeOfDayPreset.Night)
        {
            sky.SkyMaterial = new ProceduralSkyMaterial
            {
                SkyTopColor = new Color(0.01f, 0.02f, 0.06f),
                SkyHorizonColor = new Color(0.07f, 0.12f, 0.24f),
                GroundBottomColor = new Color(0.02f, 0.03f, 0.05f),
                GroundHorizonColor = new Color(0.05f, 0.08f, 0.15f),
                SunAngleMax = 12f,
                SunCurve = 0.12f
            };
        }
        else
        {
            sky.SkyMaterial = new ProceduralSkyMaterial
            {
                SkyTopColor = new Color(0.09f, 0.34f, 0.80f),
                SkyHorizonColor = new Color(0.66f, 0.85f, 0.99f),
                GroundBottomColor = new Color(0.14f, 0.24f, 0.13f),
                GroundHorizonColor = new Color(0.58f, 0.72f, 0.82f),
                SunAngleMax = 22f,
                SunCurve = 0.07f
            };
        }

        _worldEnv.Environment = new Godot.Environment
        {
            BackgroundMode = Godot.Environment.BGMode.Sky,
            Sky = sky,
            AmbientLightSource = Godot.Environment.AmbientSource.Sky,
            ReflectedLightSource = Godot.Environment.ReflectionSource.Sky,
            AmbientLightSkyContribution = preset == TimeOfDayPreset.Night ? 0.58f : 0.92f,
            AmbientLightEnergy = preset == TimeOfDayPreset.Night ? 0.68f : 1.08f,
            TonemapMode = Godot.Environment.ToneMapper.Aces,
            TonemapExposure = preset == TimeOfDayPreset.Night ? 1.18f : 1.08f,
            AdjustmentEnabled = true,
            AdjustmentContrast = 1.08f,
            AdjustmentSaturation = 1.12f,
            GlowEnabled = true,
            GlowIntensity = preset == TimeOfDayPreset.Night ? 0.58f : 0.36f,
            GlowBloom = preset == TimeOfDayPreset.Night ? 0.20f : 0.10f,
            FogEnabled = true,
            FogLightColor = preset == TimeOfDayPreset.Sunset
                ? new Color(0.88f, 0.52f, 0.32f)
                : (preset == TimeOfDayPreset.Night ? new Color(0.06f, 0.10f, 0.19f) : new Color(0.70f, 0.84f, 0.96f)),
            FogDensity = preset == TimeOfDayPreset.Night ? 0.00105f : 0.00062f
        };

        if (preset == TimeOfDayPreset.Sunset)
        {
            _sunLight.LightColor = new Color(1.0f, 0.68f, 0.38f);
            _sunLight.LightEnergy = 1.50f;
            _sunLight.RotationDegrees = new Vector3(-16f, -52f, 0f);
        }
        else if (preset == TimeOfDayPreset.Night)
        {
            _sunLight.LightColor = new Color(0.55f, 0.70f, 0.96f);
            _sunLight.LightEnergy = 0.44f;
            _sunLight.RotationDegrees = new Vector3(-48f, 25f, 0f);
        }
        else
        {
            _sunLight.LightColor = new Color(1.0f, 0.97f, 0.90f);
            _sunLight.LightEnergy = 1.78f;
            _sunLight.RotationDegrees = new Vector3(-38f, -35f, 0f);
        }

        _track?.SetNightMode(preset == TimeOfDayPreset.Night);
    }
}

