using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public static class MeshPrimitives3D
{
    private static void AddOrientedQuad(
        SurfaceTool st,
        Vector3 a, Vector3 b, Vector3 c, Vector3 d,
        Vector2 uvA, Vector2 uvB, Vector2 uvC, Vector2 uvD,
        Vector3 hintNormal)
    {
        Vector3 n = (c - a).Cross(b - a);
        if (n.Dot(hintNormal) >= 0f)
        {
            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvB); st.AddVertex(b);
            st.SetUV(uvC); st.AddVertex(c);

            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvC); st.AddVertex(c);
            st.SetUV(uvD); st.AddVertex(d);
        }
        else
        {
            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvC); st.AddVertex(c);
            st.SetUV(uvB); st.AddVertex(b);

            st.SetUV(uvA); st.AddVertex(a);
            st.SetUV(uvD); st.AddVertex(d);
            st.SetUV(uvC); st.AddVertex(c);
        }
    }

    /// <summary>
    /// Creates a high-resolution anatomically lofted Y-axis limb mesh (from Y = -0.5 to Y = +0.5)
    /// with custom oval radii (rx, rz) and subtle fabric crease rings for photorealistic driver arms & cuffs.
    /// </summary>
    public static ArrayMesh CreateLoftedLimbMesh((float yNorm, float rx, float rz)[] stations, int radialSteps = 28, bool capEnds = true)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        int m = stations.Length;
        Vector3[][] rings = new Vector3[m][];
        for (int s = 0; s < m; s++)
        {
            var stn = stations[s];
            float y = stn.yNorm - 0.5f;
            rings[s] = new Vector3[radialSteps];
            for (int r = 0; r < radialSteps; r++)
            {
                float a = (r / (float)radialSteps) * Mathf.Tau;
                rings[s][r] = new Vector3(Mathf.Cos(a) * stn.rx, y, Mathf.Sin(a) * stn.rz);
            }
        }

        for (int s = 0; s < m - 1; s++)
        {
            float v0 = stations[s].yNorm;
            float v1 = stations[s + 1].yNorm;
            float yMid = (stations[s].yNorm + stations[s + 1].yNorm) * 0.5f - 0.5f;
            Vector3 axisCenter = new Vector3(0f, yMid, 0f);
            for (int r = 0; r < radialSteps; r++)
            {
                int rn = (r + 1) % radialSteps;
                float u0 = r / (float)radialSteps;
                float u1 = (r + 1) / (float)radialSteps;
                Vector3 p00 = rings[s][r];
                Vector3 p01 = rings[s][rn];
                Vector3 p11 = rings[s + 1][rn];
                Vector3 p10 = rings[s + 1][r];
                Vector3 quadMid = (p00 + p01 + p11 + p10) * 0.25f;
                AddOrientedQuad(st, p00, p10, p11, p01, new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), quadMid - axisCenter);
            }
        }

        if (capEnds && m >= 2)
        {
            Vector3 botC = new Vector3(0f, stations[0].yNorm - 0.5f, 0f);
            Vector3 topC = new Vector3(0f, stations[m - 1].yNorm - 0.5f, 0f);
            for (int r = 0; r < radialSteps; r++)
            {
                int rn = (r + 1) % radialSteps;
                // Bottom cap (-Y)
                Vector3 b0 = rings[0][r];
                Vector3 b1 = rings[0][rn];
                Vector3 bn = (b1 - botC).Cross(b0 - botC);
                if (bn.Dot(Vector3.Down) >= 0f)
                {
                    st.SetUV(new Vector2(0.5f, 0.5f)); st.AddVertex(botC);
                    st.SetUV(new Vector2(0.5f, 0.0f)); st.AddVertex(b0);
                    st.SetUV(new Vector2(0.5f, 0.0f)); st.AddVertex(b1);
                }
                else
                {
                    st.SetUV(new Vector2(0.5f, 0.5f)); st.AddVertex(botC);
                    st.SetUV(new Vector2(0.5f, 0.0f)); st.AddVertex(b1);
                    st.SetUV(new Vector2(0.5f, 0.0f)); st.AddVertex(b0);
                }
                // Top cap (+Y)
                Vector3 t0 = rings[m - 1][r];
                Vector3 t1 = rings[m - 1][rn];
                Vector3 tn = (t1 - topC).Cross(t0 - topC);
                if (tn.Dot(Vector3.Up) >= 0f)
                {
                    st.SetUV(new Vector2(0.5f, 0.5f)); st.AddVertex(topC);
                    st.SetUV(new Vector2(0.5f, 1.0f)); st.AddVertex(t0);
                    st.SetUV(new Vector2(0.5f, 1.0f)); st.AddVertex(t1);
                }
                else
                {
                    st.SetUV(new Vector2(0.5f, 0.5f)); st.AddVertex(topC);
                    st.SetUV(new Vector2(0.5f, 1.0f)); st.AddVertex(t1);
                    st.SetUV(new Vector2(0.5f, 1.0f)); st.AddVertex(t0);
                }
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    public static ArrayMesh CreateRevolvedTireTread(float radius, float width, int radialSteps = 40)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        float hw = width * 0.5f;
        (float x, float r)[] profile =
        {
            (-hw, radius * 0.83f),
            (-hw * 0.97f, radius * 0.94f),
            (-hw * 0.88f, radius * 0.985f),
            (-hw * 0.72f, radius * 0.998f),
            (-hw * 0.38f, radius * 1.003f),
            (0f, radius * 1.006f),
            (hw * 0.38f, radius * 1.003f),
            (hw * 0.72f, radius * 0.998f),
            (hw * 0.88f, radius * 0.985f),
            (hw * 0.97f, radius * 0.94f),
            (hw, radius * 0.83f)
        };

        for (int p = 0; p < profile.Length - 1; p++)
        {
            float u0 = p / (float)(profile.Length - 1);
            float u1 = (p + 1) / (float)(profile.Length - 1);
            for (int i = 0; i < radialSteps; i++)
            {
                float a0 = (i / (float)radialSteps) * Mathf.Tau;
                float a1 = ((i + 1) / (float)radialSteps) * Mathf.Tau;
                float v0 = (i / (float)radialSteps) * 3.0f;
                float v1 = ((i + 1) / (float)radialSteps) * 3.0f;

                Vector3 p00 = new Vector3(profile[p].x, Mathf.Sin(a0) * profile[p].r, Mathf.Cos(a0) * profile[p].r);
                Vector3 p10 = new Vector3(profile[p + 1].x, Mathf.Sin(a0) * profile[p + 1].r, Mathf.Cos(a0) * profile[p + 1].r);
                Vector3 p11 = new Vector3(profile[p + 1].x, Mathf.Sin(a1) * profile[p + 1].r, Mathf.Cos(a1) * profile[p + 1].r);
                Vector3 p01 = new Vector3(profile[p].x, Mathf.Sin(a1) * profile[p].r, Mathf.Cos(a1) * profile[p].r);

                float am = (a0 + a1) * 0.5f;
                Vector3 outDir = new Vector3(0f, Mathf.Sin(am), Mathf.Cos(am));
                AddOrientedQuad(st, p00, p10, p11, p01, new Vector2(u0, v0), new Vector2(u1, v0), new Vector2(u1, v1), new Vector2(u0, v1), outDir);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    public static ArrayMesh CreateTireSidewallDisc(float radius, float xPos, float xDir, int radialSteps = 40)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        Vector3 center = new Vector3(xPos, 0f, 0f);
        Vector2 uvCenter = new Vector2(0.5f, 0.5f);
        Vector3 normal = new Vector3(xDir, 0f, 0f);

        for (int i = 0; i < radialSteps; i++)
        {
            float a0 = (i / (float)radialSteps) * Mathf.Tau;
            float a1 = ((i + 1) / (float)radialSteps) * Mathf.Tau;

            Vector3 p0 = new Vector3(xPos, Mathf.Sin(a0) * radius, Mathf.Cos(a0) * radius);
            Vector3 p1 = new Vector3(xPos, Mathf.Sin(a1) * radius, Mathf.Cos(a1) * radius);
            Vector2 uv0 = new Vector2(0.5f + Mathf.Cos(a0) * 0.5f, 0.5f + Mathf.Sin(a0) * 0.5f);
            Vector2 uv1 = new Vector2(0.5f + Mathf.Cos(a1) * 0.5f, 0.5f + Mathf.Sin(a1) * 0.5f);

            Vector3 triN = (p1 - center).Cross(p0 - center);
            if (triN.Dot(normal) >= 0f)
            {
                st.SetUV(uvCenter); st.AddVertex(center);
                st.SetUV(uv0); st.AddVertex(p0);
                st.SetUV(uv1); st.AddVertex(p1);
            }
            else
            {
                st.SetUV(uvCenter); st.AddVertex(center);
                st.SetUV(uv1); st.AddVertex(p1);
                st.SetUV(uv0); st.AddVertex(p0);
            }
        }

        st.GenerateNormals();
        return st.Commit();
    }

    public static ArrayMesh CreateTubeAlongPath(Vector3[] path, float[] rxList, float[] ryList, int ringSegs = 20)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        int n = path.Length;
        Vector3[][] rings = new Vector3[n][];
        Vector3 prevTangent = Vector3.Forward;
        Vector3 prevSide = Vector3.Right;

        // Bishop Parallel-Transport Frame: guarantees ZERO 90/180-deg flip or hourglass pinch on vertical/curved tubes (Halo pillar & hoop)!
        for (int i = 0; i < n; i++)
        {
            Vector3 tangent;
            if (i == 0) tangent = (path[1] - path[0]).Normalized();
            else if (i == n - 1) tangent = (path[n - 1] - path[n - 2]).Normalized();
            else tangent = (path[i + 1] - path[i - 1]).Normalized();

            Vector3 side;
            if (i == 0)
            {
                Vector3 upRef = Mathf.Abs(tangent.Dot(Vector3.Up)) > 0.85f ? Vector3.Forward : Vector3.Up;
                side = tangent.Cross(upRef).Normalized();
            }
            else
            {
                Vector3 rotAxis = prevTangent.Cross(tangent);
                float axisLen = rotAxis.Length();
                if (axisLen > 0.00001f)
                {
                    float angle = Mathf.Acos(Mathf.Clamp(prevTangent.Dot(tangent), -1f, 1f));
                    side = prevSide.Rotated(rotAxis / axisLen, angle);
                }
                else
                {
                    side = prevSide;
                }
                side = (side - tangent * side.Dot(tangent)).Normalized();
                if (side.LengthSquared() < 0.001f)
                {
                    Vector3 fallbackRef = Mathf.Abs(tangent.Dot(Vector3.Up)) > 0.85f ? Vector3.Forward : Vector3.Up;
                    side = tangent.Cross(fallbackRef).Normalized();
                }
            }
            Vector3 up = side.Cross(tangent).Normalized();
            prevTangent = tangent;
            prevSide = side;

            rings[i] = new Vector3[ringSegs];
            float rx = rxList[i];
            float ry = ryList[i];
            for (int r = 0; r < ringSegs; r++)
            {
                float a = (r / (float)ringSegs) * Mathf.Tau;
                rings[i][r] = path[i] + side * (Mathf.Cos(a) * rx) + up * (Mathf.Sin(a) * ry);
            }
        }

        for (int i = 0; i < n - 1; i++)
        {
            float v0 = i / (float)(n - 1) * 3.0f;
            float v1 = (i + 1) / (float)(n - 1) * 3.0f;
            for (int r = 0; r < ringSegs; r++)
            {
                int rn = (r + 1) % ringSegs;
                float u0 = r / (float)ringSegs;
                float u1 = (r + 1) / (float)ringSegs;

                Vector3 p00 = rings[i][r];
                Vector3 p01 = rings[i][rn];
                Vector3 p11 = rings[i + 1][rn];
                Vector3 p10 = rings[i + 1][r];
                Vector3 midRing = (path[i] + path[i + 1]) * 0.5f;
                Vector3 quadCenter = (p00 + p01 + p11 + p10) * 0.25f;
                AddOrientedQuad(st, p00, p10, p11, p01, new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), quadCenter - midRing);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    public static ArrayMesh CreateSculptedNoseconeMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // Extended smoothly from cockpit coaming (-0.58) all the way to tapered FIA nose tip (-3.08)!
        (float z, float hw, float topY, float botY, float crown)[] stations =
        {
            (-0.58f, 0.43f, 0.638f, 0.22f, 0.048f),
            (-0.82f, 0.40f, 0.630f, 0.22f, 0.050f),
            (-1.14f, 0.35f, 0.592f, 0.21f, 0.050f),
            (-1.52f, 0.295f, 0.528f, 0.20f, 0.046f),
            (-1.94f, 0.240f, 0.452f, 0.19f, 0.040f),
            (-2.36f, 0.185f, 0.374f, 0.18f, 0.034f),
            (-2.74f, 0.135f, 0.295f, 0.17f, 0.026f),
            (-3.08f, 0.086f, 0.220f, 0.16f, 0.016f)
        };

        const int arcPts = 20;
        Vector3[][] rings = new Vector3[stations.Length][];

        for (int s = 0; s < stations.Length; s++)
        {
            var stn = stations[s];
            rings[s] = new Vector3[arcPts];
            for (int k = 0; k < arcPts; k++)
            {
                float t = k / (float)(arcPts - 1);
                float ang = Mathf.Pi * (1.0f - t);
                float x = Mathf.Cos(ang) * stn.hw;
                // Clamp >= 0f so sin(Pi) float precision (-8.7e-8) NEVER produces NaN in Pow!
                float sinA = Mathf.Max(0f, Mathf.Sin(ang));
                float y = stn.botY + (stn.topY - stn.botY) * Mathf.Pow(sinA, 0.55f) + stn.crown * (sinA * sinA);
                rings[s][k] = new Vector3(x, y, stn.z);
            }
        }

        for (int s = 0; s < stations.Length - 1; s++)
        {
            float v0 = s / (float)(stations.Length - 1);
            float v1 = (s + 1) / (float)(stations.Length - 1);
            Vector3 center = new Vector3(0f, 0.20f, (stations[s].z + stations[s + 1].z) * 0.5f);
            for (int k = 0; k < arcPts - 1; k++)
            {
                float u0 = k / (float)(arcPts - 1);
                float u1 = (k + 1) / (float)(arcPts - 1);
                Vector3 a = rings[s][k];
                Vector3 b = rings[s + 1][k];
                Vector3 c = rings[s + 1][k + 1];
                Vector3 d = rings[s][k + 1];
                Vector3 mid = (a + b + c + d) * 0.25f;
                AddOrientedQuad(st, a, b, c, d, new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), mid - center);
            }
        }

        var last = rings[stations.Length - 1];
        Vector3 tipCenter = new Vector3(0f, 0.19f, -3.14f);
        for (int k = 0; k < arcPts - 1; k++)
        {
            Vector3 p0 = last[k];
            Vector3 p1 = last[k + 1];
            Vector3 triN = (p1 - tipCenter).Cross(p0 - tipCenter);
            if (triN.Dot(Vector3.Forward) >= 0f)
            {
                st.SetUV(new Vector2(0.5f, 1f)); st.AddVertex(tipCenter);
                st.SetUV(new Vector2(0.4f, 0.9f)); st.AddVertex(p0);
                st.SetUV(new Vector2(0.6f, 0.9f)); st.AddVertex(p1);
            }
            else
            {
                st.SetUV(new Vector2(0.5f, 1f)); st.AddVertex(tipCenter);
                st.SetUV(new Vector2(0.6f, 0.9f)); st.AddVertex(p1);
                st.SetUV(new Vector2(0.4f, 0.9f)); st.AddVertex(p0);
            }
        }


        // Solid nose underside belly so zero light/asphalt ever leaks under the chassis
        for (int s = 0; s < stations.Length - 1; s++)
        {
            Vector3 l0 = rings[s][0];
            Vector3 r0 = rings[s][arcPts - 1];
            Vector3 l1 = rings[s + 1][0];
            Vector3 r1 = rings[s + 1][arcPts - 1];
            AddOrientedQuad(st, l0, r0, r1, l1, new Vector2(0, 0), new Vector2(1, 0), new Vector2(1, 1), new Vector2(0, 1), Vector3.Down);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates a sculpted, curved 2024 ground-effect F1 Engine Cover & Airbox Cowling (from roll-hoop back to rear gearbox).
    /// </summary>

    /// <summary>
    /// Creates a thin, curved, surface-conforming center racing stripe along the sculpted nosecone crest
    /// (zero floating edges or box clipping!).
    /// </summary>
    public static ArrayMesh CreateNoseStripeMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        (float z, float hw, float topY, float botY, float crown)[] stations =
        {
            (-1.26f, 0.332f, 0.572f, 0.207f, 0.049f),
            (-1.52f, 0.295f, 0.528f, 0.200f, 0.046f),
            (-1.94f, 0.240f, 0.452f, 0.190f, 0.040f),
            (-2.36f, 0.185f, 0.374f, 0.180f, 0.034f),
            (-2.74f, 0.135f, 0.295f, 0.170f, 0.026f),
            (-3.04f, 0.092f, 0.228f, 0.161f, 0.017f)
        };

        const int arcPts = 7;
        Vector3[][] rings = new Vector3[stations.Length][];
        for (int s = 0; s < stations.Length; s++)
        {
            var stn = stations[s];
            float stripeHalfW = Mathf.Min(0.034f, stn.hw * 0.34f);
            rings[s] = new Vector3[arcPts];
            for (int k = 0; k < arcPts; k++)
            {
                float frac = (k / (float)(arcPts - 1)) * 2f - 1f; // -1 .. +1
                float x = frac * stripeHalfW;
                float cosA = Mathf.Clamp(x / stn.hw, -0.99f, 0.99f);
                float sinA = Mathf.Sqrt(Mathf.Max(0f, 1f - cosA * cosA));
                float y = stn.botY + (stn.topY - stn.botY) * Mathf.Pow(sinA, 0.55f) + stn.crown * (sinA * sinA) + 0.0028f;
                rings[s][k] = new Vector3(x, y, stn.z);
            }
        }

        for (int s = 0; s < stations.Length - 1; s++)
        {
            float v0 = s / (float)(stations.Length - 1);
            float v1 = (s + 1) / (float)(stations.Length - 1);
            for (int k = 0; k < arcPts - 1; k++)
            {
                float u0 = k / (float)(arcPts - 1);
                float u1 = (k + 1) / (float)(arcPts - 1);
                AddOrientedQuad(st, rings[s][k], rings[s + 1][k], rings[s + 1][k + 1], rings[s][k + 1],
                    new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), Vector3.Up);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    public static ArrayMesh CreateSculptedEngineCoverMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // (z, halfWidth, topY, botY)
