                AddOrientedQuad(st, a, b, c, d, new Vector2(u0, v0), new Vector2(u0, v1), new Vector2(u1, v1), new Vector2(u1, v0), mid - center);
            }
        }

        // Front airbox face & rear tail cap
        Vector3 frontC = new Vector3(0f, 0.56f, stations[0].z);
        Vector3 backC = new Vector3(0f, 0.34f, stations[stations.Length - 1].z);
        for (int k = 0; k < arcPts - 1; k++)
        {
            Vector3 f0 = rings[0][k];
            Vector3 f1 = rings[0][k + 1];
            AddOrientedQuad(st, frontC, f0, f1, frontC, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector3.Forward);
            Vector3 b0 = rings[stations.Length - 1][k];
            Vector3 b1 = rings[stations.Length - 1][k + 1];
            AddOrientedQuad(st, backC, b1, b0, backC, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector3.Back);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates a sculpted, rounded F1 Sidepod with downwash ramp & undercut (side = -1 left, +1 right).
    /// </summary>
    public static ArrayMesh CreateSculptedSidepodMesh(float side)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // (z, innerX, outerX, topY, botY)
        (float z, float inX, float outX, float topY, float botY)[] stations =
        {
            (-0.68f, 0.30f, 0.72f, 0.54f, 0.22f), // Front radiator intake lip
            (-0.30f, 0.32f, 0.79f, 0.58f, 0.16f), // Wide shoulder max width
            ( 0.25f, 0.30f, 0.76f, 0.54f, 0.16f), // Mid sidepod downwash
            ( 0.80f, 0.24f, 0.62f, 0.44f, 0.16f), // Coke-bottle sweep inward
            ( 1.25f, 0.16f, 0.40f, 0.33f, 0.17f)  // Rear floor merge
        };

        const int ringPts = 12;
        Vector3[][] rings = new Vector3[stations.Length][];
        for (int s = 0; s < stations.Length; s++)
        {
            var stn = stations[s];
            float cx = side * (stn.inX + stn.outX) * 0.5f;
            float rx = (stn.outX - stn.inX) * 0.5f;
            float cy = (stn.botY + stn.topY) * 0.5f;
            float ry = (stn.topY - stn.botY) * 0.5f;
            rings[s] = new Vector3[ringPts];
            for (int r = 0; r < ringPts; r++)
            {
                float a = (r / (float)ringPts) * Mathf.Tau;
                rings[s][r] = new Vector3(cx + Mathf.Cos(a) * rx, cy + Mathf.Sin(a) * ry, stn.z);
            }
        }

        for (int s = 0; s < stations.Length - 1; s++)
        {
            float v0 = s / (float)(stations.Length - 1);
            float v1 = (s + 1) / (float)(stations.Length - 1);
            float midX = side * ((stations[s].inX + stations[s].outX + stations[s + 1].inX + stations[s + 1].outX) * 0.25f);
            float midY = (stations[s].botY + stations[s].topY + stations[s + 1].botY + stations[s + 1].topY) * 0.25f;
            Vector3 center = new Vector3(midX, midY, (stations[s].z + stations[s + 1].z) * 0.5f);
            for (int r = 0; r < ringPts; r++)
            {
                int rn = (r + 1) % ringPts;
                Vector3 a = rings[s][r];
                Vector3 b = rings[s + 1][r];
                Vector3 c = rings[s + 1][rn];
                Vector3 d = rings[s][rn];
                Vector3 quadMid = (a + b + c + d) * 0.25f;
                AddOrientedQuad(st, a, b, c, d, new Vector2(r / (float)ringPts, v0), new Vector2(r / (float)ringPts, v1), new Vector2((r + 1) / (float)ringPts, v1), new Vector2((r + 1) / (float)ringPts, v0), quadMid - center);
            }
        }

        // Front intake cap & rear cap
        Vector3 fC = new Vector3(side * 0.51f, 0.38f, stations[0].z);
        Vector3 bC = new Vector3(side * 0.28f, 0.25f, stations[stations.Length - 1].z);
        for (int r = 0; r < ringPts; r++)
        {
            int rn = (r + 1) % ringPts;
            AddOrientedQuad(st, fC, rings[0][r], rings[0][rn], fC, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector3.Forward);
            AddOrientedQuad(st, bC, rings[stations.Length - 1][rn], rings[stations.Length - 1][r], bC, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector3.Back);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }


    private static void AddBoxToSurface(SurfaceTool st, Vector3 center, Vector3 size, Vector3 rotDeg)
    {
        Basis b = Basis.FromEuler(new Vector3(Mathf.DegToRad(rotDeg.X), Mathf.DegToRad(rotDeg.Y), Mathf.DegToRad(rotDeg.Z)));
        Vector3 hx = b.X * (size.X * 0.5f);
        Vector3 hy = b.Y * (size.Y * 0.5f);
        Vector3 hz = b.Z * (size.Z * 0.5f);

        Vector3 p000 = center - hx - hy - hz;
        Vector3 p100 = center + hx - hy - hz;
        Vector3 p110 = center + hx + hy - hz;
        Vector3 p010 = center - hx + hy - hz;
        Vector3 p001 = center - hx - hy + hz;
        Vector3 p101 = center + hx - hy + hz;
        Vector3 p111 = center + hx + hy + hz;
        Vector3 p011 = center - hx + hy + hz;

        Vector2 u0 = new(0, 0), u1 = new(1, 0), u2 = new(1, 1), u3 = new(0, 1);
        AddOrientedQuad(st, p001, p101, p111, p011, u0, u1, u2, u3, b.Z);
        AddOrientedQuad(st, p100, p000, p010, p110, u0, u1, u2, u3, -b.Z);
        AddOrientedQuad(st, p101, p100, p110, p111, u0, u1, u2, u3, b.X);
        AddOrientedQuad(st, p000, p001, p011, p010, u0, u1, u2, u3, -b.X);
        AddOrientedQuad(st, p011, p111, p110, p010, u0, u1, u2, u3, b.Y);
        AddOrientedQuad(st, p000, p100, p101, p001, u0, u1, u2, u3, -b.Y);
    }

    /// <summary>
    /// Creates a crisp 3D human spectator torso + shoulders + arms (facing +Z, origin at seat/hip level Y=0).
    /// When armsRaised == true, the fan is standing/cheering with both arms raised in celebration!
    /// </summary>
    public static ArrayMesh CreateSpectatorBodyMesh(bool armsRaised)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        float yOff = armsRaised ? 0.14f : 0.0f;
        // Main upper torso / jersey
        AddBoxToSurface(st, new Vector3(0f, 0.34f + yOff, 0f), new Vector3(0.42f, 0.52f, 0.24f), Vector3.Zero);
        // Slightly broader shoulder line
        AddBoxToSurface(st, new Vector3(0f, 0.56f + yOff, 0f), new Vector3(0.50f, 0.14f, 0.24f), Vector3.Zero);
        // Seated lap / lower hips
        AddBoxToSurface(st, new Vector3(0f, 0.08f + yOff * 0.5f, 0.14f), new Vector3(0.40f, 0.18f, 0.34f), Vector3.Zero);

        if (armsRaised)
        {
            // Both arms raised high cheering!
            AddBoxToSurface(st, new Vector3(-0.31f, 0.80f + yOff, 0.05f), new Vector3(0.13f, 0.50f, 0.13f), new Vector3(-16f, 0f, 20f));
            AddBoxToSurface(st, new Vector3( 0.31f, 0.80f + yOff, 0.05f), new Vector3(0.13f, 0.50f, 0.13f), new Vector3(-16f, 0f, -20f));
        }
        else
        {
            // Relaxed seated arms resting forward
            AddBoxToSurface(st, new Vector3(-0.27f, 0.34f, 0.06f), new Vector3(0.13f, 0.42f, 0.14f), new Vector3(-18f, 0f, 6f));
            AddBoxToSurface(st, new Vector3( 0.27f, 0.34f, 0.06f), new Vector3(0.13f, 0.42f, 0.14f), new Vector3(-18f, 0f, -6f));
        }

        st.GenerateNormals();
        return st.Commit();
    }

