    /// <summary>
    /// Creates the organic, wide flared Y-junction fairing where the central F1 Halo pillar blends
    /// smoothly upward and outward into the left & right arms of the Halo hoop (like real F1/McLaren Halos!).
    /// </summary>
    public static ArrayMesh CreateHaloYJunctionMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // Stations rising from central pillar throat (Y=0.805) up into wide arched hoop brow (Y=0.952)
        // Tightened Z so the curved dark inner sponsor fascia ribbon sits 100% visible in front of the Halo!
        (float y, float z, float hw, float dz)[] stns =
        {
            (0.805f, -0.912f, 0.020f, 0.034f),
            (0.845f, -0.924f, 0.034f, 0.034f),
            (0.878f, -0.930f, 0.068f, 0.034f),
            (0.906f, -0.932f, 0.125f, 0.033f),
            (0.930f, -0.928f, 0.192f, 0.031f),
            (0.948f, -0.922f, 0.250f, 0.029f)
        };

        const int ringPts = 18;
        Vector3[][] rings = new Vector3[stns.Length][];
        for (int s = 0; s < stns.Length; s++)
        {
            var stn = stns[s];
            rings[s] = new Vector3[ringPts];
            for (int r = 0; r < ringPts; r++)
            {
                float a = (r / (float)ringPts) * Mathf.Tau;
                float x = Mathf.Cos(a) * stn.hw;
                // Follow the Halo's natural rearward sweep as |x| grows
                float zSweep = (x * x) * 1.45f;
                float z = stn.z + zSweep + Mathf.Sin(a) * stn.dz;
                float yLift = Mathf.Abs(x) * 0.04f;
                rings[s][r] = new Vector3(x, stn.y + yLift, z);
            }
        }

        for (int s = 0; s < stns.Length - 1; s++)
        {
            float v0 = s / (float)(stns.Length - 1);
            float v1 = (s + 1) / (float)(stns.Length - 1);
            Vector3 center = new Vector3(0f, (stns[s].y + stns[s + 1].y) * 0.5f, (stns[s].z + stns[s + 1].z) * 0.5f);
            for (int r = 0; r < ringPts; r++)
            {
                int rn = (r + 1) % ringPts;
                Vector3 a = rings[s][r];
                Vector3 b = rings[s + 1][r];
                Vector3 c = rings[s + 1][rn];
                Vector3 d = rings[s][rn];
                Vector3 mid = (a + b + c + d) * 0.25f;
                AddOrientedQuad(st, a, b, c, d,
                    new Vector2(r / (float)ringPts, v0), new Vector2(r / (float)ringPts, v1),
                    new Vector2((r + 1) / (float)ringPts, v1), new Vector2((r + 1) / (float)ringPts, v0),
                    mid - center);
            }
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates the curved dark inner sponsor fascia ribbon running across the upper inner brow of the F1 Halo
    /// (facing the driver camera, framing the team sponsor logo just like the VELO brow in the reference photo!).
    /// </summary>
    public static ArrayMesh CreateHaloInnerSponsorStripMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        const int segs = 20;
        Vector3[] topPts = new Vector3[segs];
        Vector3[] botPts = new Vector3[segs];
        for (int i = 0; i < segs; i++)
        {
            float f = (i / (float)(segs - 1)) * 2f - 1f; // -1 .. +1
            float x = f * 0.295f;
            // Sits cleanly +6mm on the driver-facing inner surface of the Halo brow (ZERO burial!)
            float z = -0.884f + (x * x) * 2.55f;
            float yMid = 0.956f - (x * x) * 0.08f;
            topPts[i] = new Vector3(x, yMid + 0.018f, z);
            botPts[i] = new Vector3(x, yMid - 0.018f, z + 0.005f);
        }

        for (int i = 0; i < segs - 1; i++)
        {
            float u0 = i / (float)(segs - 1);
            float u1 = (i + 1) / (float)(segs - 1);
            AddOrientedQuad(st, botPts[i], topPts[i], topPts[i + 1], botPts[i + 1],
                new Vector2(u0, 1), new Vector2(u0, 0), new Vector2(u1, 0), new Vector2(u1, 1), Vector3.Back);
        }

        st.GenerateNormals();
        return st.Commit();
    }

    /// <summary>
    /// Creates a curved sculpted carbon-fiber dash cowling / instrument brow arching cleanly behind the nosecone
    /// and over the steering wheel cavity.
    /// </summary>
    public static ArrayMesh CreateCockpitDashLipMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        const int segs = 22;
        Vector3[] frontPts = new Vector3[segs];
        Vector3[] backPts = new Vector3[segs];
        Vector3[] innerPts = new Vector3[segs];

        for (int i = 0; i < segs; i++)
        {
            float f = (i / (float)(segs - 1)) * 2f - 1f; // -1 .. +1
            float x = f * 0.385f;
            float arch = Mathf.Sqrt(Mathf.Max(0f, 1f - f * f * 0.88f));
            float y = 0.565f + arch * 0.095f;
            float zFront = -0.665f + (f * f) * 0.065f;
            float zBack = zFront + 0.072f;
            frontPts[i] = new Vector3(x, y, zFront);
            backPts[i] = new Vector3(x, y - 0.008f, zBack);
            innerPts[i] = new Vector3(x, y - 0.055f, zBack - 0.015f);
        }

        for (int i = 0; i < segs - 1; i++)
        {
            float u0 = i / (float)(segs - 1);
            float u1 = (i + 1) / (float)(segs - 1);
            AddOrientedQuad(st, frontPts[i], backPts[i], backPts[i + 1], frontPts[i + 1],
                new Vector2(u0, 0), new Vector2(u0, 1), new Vector2(u1, 1), new Vector2(u1, 0), Vector3.Up);
            AddOrientedQuad(st, backPts[i], innerPts[i], innerPts[i + 1], backPts[i + 1],
                new Vector2(u0, 0), new Vector2(u0, 1), new Vector2(u1, 1), new Vector2(u1, 0), Vector3.Back);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates a sleek sculpted rounded aerodynamic teardrop F1 side mirror housing (replaces boxy cubes!).
    /// Local origin is at the mirror center, facing rear (+Z is mirror glass face, -Z is streamlined aero nose).
    /// </summary>
    public static ArrayMesh CreateAeroMirrorHousingMesh()
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // (z, halfW, halfH) from front streamlined aero nose (-0.065) back to bezel lip (+0.042)
        (float z, float rx, float ry)[] stns =
        {
            (-0.068f, 0.014f, 0.009f),
            (-0.048f, 0.048f, 0.024f),
            (-0.016f, 0.074f, 0.034f),
            ( 0.018f, 0.078f, 0.036f),
            ( 0.044f, 0.074f, 0.034f)
        };

        const int ringPts = 20;
        Vector3[][] rings = new Vector3[stns.Length][];
        for (int s = 0; s < stns.Length; s++)
        {
            var stn = stns[s];
            rings[s] = new Vector3[ringPts];
            for (int r = 0; r < ringPts; r++)
            {
                float a = (r / (float)ringPts) * Mathf.Tau;
                float ca = Mathf.Cos(a);
                float sa = Mathf.Sin(a);
                // Slightly flatter bottom, rounder aero crown top
                float ryMod = sa > 0 ? stn.ry * 1.05f : stn.ry * 0.85f;
                rings[s][r] = new Vector3(ca * stn.rx, sa * ryMod, stn.z);
            }
        }

        for (int s = 0; s < stns.Length - 1; s++)
        {
            Vector3 cMid = new Vector3(0f, 0f, (stns[s].z + stns[s + 1].z) * 0.5f);
            for (int r = 0; r < ringPts; r++)
            {
                int rn = (r + 1) % ringPts;
                Vector3 a = rings[s][r];
                Vector3 b = rings[s + 1][r];
                Vector3 c = rings[s + 1][rn];
                Vector3 d = rings[s][rn];
                AddOrientedQuad(st, a, b, c, d,
                    new Vector2(r / (float)ringPts, s / (float)(stns.Length - 1)),
                    new Vector2(r / (float)ringPts, (s + 1) / (float)(stns.Length - 1)),
                    new Vector2((r + 1) / (float)ringPts, (s + 1) / (float)(stns.Length - 1)),
                    new Vector2((r + 1) / (float)ringPts, s / (float)(stns.Length - 1)),
                    ((a + b + c + d) * 0.25f) - cMid);
            }
        }

        // Front aerodynamic tip cap & recessed rear mirror bezel backing
        Vector3 frontTip = new Vector3(0f, 0f, -0.075f);
        Vector3 backC = new Vector3(0f, 0f, 0.040f);
        for (int r = 0; r < ringPts; r++)
        {
            int rn = (r + 1) % ringPts;
            AddOrientedQuad(st, frontTip, rings[0][r], rings[0][rn], frontTip, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector3.Forward);
            AddOrientedQuad(st, backC, rings[stns.Length - 1][rn], rings[stns.Length - 1][r], backC, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector2.Zero, Vector3.Back);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    /// <summary>
    /// Creates an authentic McLaren-style Open-Bottom Sculpted Carbon Butterfly F1 Steering Wheel body
    /// (with arched thumb-guard shoulders, central rotary pod belly, and open lower handle cutouts!).
    /// </summary>

    /// <summary>
    /// Creates a true sculpted oval mirror glass disc strictly inset INSIDE the aerodynamic mirror pod bezel
    /// (zero rectangular corners poking out!), with mirrored horizontal UVs mapping to the live rear-view SubViewport!
    /// </summary>
    public static ArrayMesh CreateRoundedMirrorGlassMesh(float rx, float ry, float uMin, float uMax, int segs = 28)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        Vector3 center = Vector3.Zero;
        float uMid = (uMin + uMax) * 0.5f;
        float uSpan = (uMax - uMin) * 0.5f;

        for (int i = 0; i < segs; i++)
        {
            float a0 = (i / (float)segs) * Mathf.Tau;
            float a1 = ((i + 1) / (float)segs) * Mathf.Tau;

            float c0 = Mathf.Cos(a0), s0 = Mathf.Sin(a0);
            float c1 = Mathf.Cos(a1), s1 = Mathf.Sin(a1);
            float ry0 = s0 > 0 ? ry * 1.04f : ry * 0.84f;
            float ry1 = s1 > 0 ? ry * 1.04f : ry * 0.84f;

            Vector3 p0 = new Vector3(c0 * rx, s0 * ry0, 0f);
            Vector3 p1 = new Vector3(c1 * rx, s1 * ry1, 0f);

            // Horizontally flipped mirror UVs (1 - x) so left/right in the rear-view mirror behaves like a real F1 mirror!
            Vector2 uvC = new Vector2(uMid, 0.5f);
            Vector2 uv0 = new Vector2(uMid - c0 * uSpan, 0.5f - s0 * 0.46f);
            Vector2 uv1 = new Vector2(uMid - c1 * uSpan, 0.5f - s1 * 0.46f);

            // Face toward +Z (rearward toward driver camera)
            Vector3 triN = (p1 - center).Cross(p0 - center);
            if (triN.Dot(Vector3.Back) >= 0f)
            {
                st.SetUV(uvC); st.AddVertex(center);
                st.SetUV(uv0); st.AddVertex(p0);
                st.SetUV(uv1); st.AddVertex(p1);
            }
            else
            {
                st.SetUV(uvC); st.AddVertex(center);
                st.SetUV(uv1); st.AddVertex(p1);
                st.SetUV(uv0); st.AddVertex(p0);
            }
        }

        st.GenerateNormals();
        return st.Commit();
    }

    public static ArrayMesh CreateMcLarenButterflyWheelMesh(float halfW, float halfH, float thickness)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        // Star-convex sculpted 22-vertex butterfly silhouette matching modern McLaren/F1 wheels!
        Vector2[] poly =
        {
            new(-0.56f * halfW,  0.96f * halfH), // Top-left brow shoulder
            new(-0.92f * halfW,  0.94f * halfH), // Left thumb-guard top horn
            new(-1.04f * halfW,  0.64f * halfH), // Left upper grip arch
            new(-0.95f * halfW,  0.14f * halfH), // Left thumbwheel waist
            new(-1.02f * halfW, -0.56f * halfH), // Left lower grip outer
            new(-0.88f * halfW, -1.04f * halfH), // Left bottom grip tip
            new(-0.68f * halfW, -0.98f * halfH), // Left grip inner bottom
            new(-0.62f * halfW, -0.62f * halfH), // Open-bottom U-cutout left corner
            new(-0.46f * halfW, -0.82f * halfH), // Central rotary pod left cheek
            new( 0.00f * halfW, -0.88f * halfH), // Central rotary pod bottom chin
            new( 0.46f * halfW, -0.82f * halfH), // Central rotary pod right cheek
            new( 0.62f * halfW, -0.62f * halfH), // Open-bottom U-cutout right corner
            new( 0.68f * halfW, -0.98f * halfH), // Right grip inner bottom
            new( 0.88f * halfW, -1.04f * halfH), // Right bottom grip tip
            new( 1.02f * halfW, -0.56f * halfH), // Right lower grip outer
            new( 0.95f * halfW,  0.14f * halfH), // Right thumbwheel waist
            new( 1.04f * halfW,  0.64f * halfH), // Right upper grip arch
            new( 0.92f * halfW,  0.94f * halfH), // Right thumb-guard top horn
            new( 0.56f * halfW,  0.96f * halfH), // Top-right brow shoulder
            new( 0.40f * halfW,  1.05f * halfH), // Raised OLED brow right
            new( 0.00f * halfW,  1.07f * halfH), // Raised OLED brow center
            new(-0.40f * halfW,  1.05f * halfH)  // Raised OLED brow left
        };

        float zFront = thickness * 0.5f;
        float zBack = -thickness * 0.5f;
        Vector3 cFront = new Vector3(0f, 0.08f * halfH, zFront);
        Vector3 cBack = new Vector3(0f, 0.08f * halfH, zBack);
        Vector2 uvMid = new Vector2(0.5f, 0.46f);

        int n = poly.Length;
        for (int i = 0; i < n; i++)
        {
            Vector2 p0 = poly[i];
            Vector2 p1 = poly[(i + 1) % n];

            Vector3 f0 = new Vector3(p0.X, p0.Y, zFront);
            Vector3 f1 = new Vector3(p1.X, p1.Y, zFront);
            Vector3 b0 = new Vector3(p0.X, p0.Y, zBack);
            Vector3 b1 = new Vector3(p1.X, p1.Y, zBack);

            Vector2 uv0 = new Vector2(p0.X / (halfW * 2.1f) + 0.5f, 0.5f - p0.Y / (halfH * 2.1f));
            Vector2 uv1 = new Vector2(p1.X / (halfW * 2.1f) + 0.5f, 0.5f - p1.Y / (halfH * 2.1f));

            Vector3 nF = (f1 - cFront).Cross(f0 - cFront);
            if (nF.Dot(Vector3.Back) >= 0f)
            {
                st.SetUV(uvMid); st.AddVertex(cFront);
                st.SetUV(uv0); st.AddVertex(f0);
                st.SetUV(uv1); st.AddVertex(f1);
            }
            else
            {
                st.SetUV(uvMid); st.AddVertex(cFront);
                st.SetUV(uv1); st.AddVertex(f1);
                st.SetUV(uv0); st.AddVertex(f0);
            }

            Vector3 nB = (b1 - cBack).Cross(b0 - cBack);
            if (nB.Dot(Vector3.Forward) >= 0f)
            {
                st.SetUV(uvMid); st.AddVertex(cBack);
                st.SetUV(uv0); st.AddVertex(b0);
                st.SetUV(uv1); st.AddVertex(b1);
            }
            else
            {
                st.SetUV(uvMid); st.AddVertex(cBack);
                st.SetUV(uv1); st.AddVertex(b1);
                st.SetUV(uv0); st.AddVertex(b0);
            }

            Vector2 edgeMid = (p0 + p1) * 0.5f;
            Vector3 outDir = new Vector3(edgeMid.X, edgeMid.Y, 0f).Normalized();
            AddOrientedQuad(st, f0, f1, b1, b0, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(0f, 1f), outDir);
        }

        st.GenerateNormals();
        st.GenerateTangents();
        return st.Commit();
    }

    public static ArrayMesh CreateButterflyWheelMesh(float halfW, float halfH, float thickness)
    {
        var st = new SurfaceTool();
        st.Begin(Mesh.PrimitiveType.Triangles);

        Vector2[] poly =
        {
