    private void BuildCenterModeDial(Vector3 pos, StandardMaterial3D metalMat, StandardMaterial3D darkMat)
    {
        var dial = new Node3D { Position = pos };
        AddChild(dial);

        // Iconic white/silver wide printed scale bezel ring (signature centerpiece of McLaren/F1 wheel!)
        dial.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.023f, BottomRadius = 0.024f, Height = 0.006f, RadialSegments = 28 },
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = new StandardMaterial3D { AlbedoColor = new Color(0.93f, 0.94f, 0.97f), Roughness = 0.24f, Metallic = 0.12f }
        });

        // 12 precision color-coded calibration ticks around the white ring
        for (int s = 0; s < 12; s++)
        {
            float ang = (s / 12f) * Mathf.Tau;
            Color tickCol = (s < 3) ? new Color(0.92f, 0.14f, 0.16f) : (s < 6 ? new Color(0.08f, 0.56f, 0.96f) : new Color(0.10f, 0.12f, 0.16f));
            dial.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.0042f, 0.0018f, 0.002f) },
                Position = new Vector3(Mathf.Cos(ang) * 0.0185f, Mathf.Sin(ang) * 0.0185f, 0.0032f),
                RotationDegrees = new Vector3(0f, 0f, Mathf.RadToDeg(ang)),
                MaterialOverride = new StandardMaterial3D { AlbedoColor = tickCol, Roughness = 0.30f }
            });
        }

        // Matte black machined central knob + sculpted pointer wing
        dial.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.0135f, BottomRadius = 0.0145f, Height = 0.012f, RadialSegments = 24 },
            Position = new Vector3(0f, 0f, 0.003f),
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = darkMat
        });
        dial.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.0045f, 0.022f, 0.006f) },
            Position = new Vector3(0.004f, -0.006f, 0.008f),
            RotationDegrees = new Vector3(0f, 0f, 28f),
            MaterialOverride = darkMat
        });
        dial.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.005f, BottomRadius = 0.005f, Height = 0.0135f, RadialSegments = 16 },
            Position = new Vector3(0f, 0f, 0.0035f),
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = metalMat
        });
    }

    private void BuildTyreRainbowDial(Vector3 pos, StandardMaterial3D metalMat, StandardMaterial3D darkMat)
