    private Node3D BuildRacingGlove3D(float side, StandardMaterial3D carbonMat, StandardMaterial3D palmGripMat)
    {
        var hand = new Node3D { Position = new Vector3(side * 0.150f, -0.010f, 0.010f) };
        AddChild(hand);

        // High-Resolution Sculpted Ergonomic Hand / Palm Shell (24 radial segments!)
        var palm = new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.033f, Height = 0.114f, RadialSegments = 24, Rings = 10 },
            Position = new Vector3(side * 0.007f, -0.010f, 0.009f),
            RotationDegrees = new Vector3(14f, side * -12f, side * 8f),
            Scale = new Vector3(0.94f, 1.0f, 0.78f),
            MaterialOverride = _gloveMat
        };
        hand.AddChild(palm);
        _gloveMeshes.Add(palm);

        // Inner Suede Grip Pad hugging the wheel handle
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.022f, Height = 0.082f, RadialSegments = 18, Rings = 6 },
            Position = new Vector3(-side * 0.006f, -0.004f, -0.003f),
            MaterialOverride = palmGripMat
        });

        // Sculpted Curved Gloss-Carbon Knuckle Protector with subtle angled ridges
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.011f, Height = 0.052f, RadialSegments = 16, Rings = 6 },
            Position = new Vector3(side * 0.006f, 0.014f, 0.029f),
            RotationDegrees = new Vector3(0f, side * -12f, 90f + side * 8f),
            Scale = new Vector3(1.0f, 1.0f, 0.55f),
            MaterialOverride = carbonMat
        });

        // 4 High-Res Individually Sculpted Curled Fingers wrapping cleanly around the Alcantara grip!
        float[] fingerY = { 0.031f, 0.012f, -0.007f, -0.025f };
        float[] fingerR = { 0.0105f, 0.0110f, 0.0105f, 0.0092f };
        float[] fingerLen = { 0.056f, 0.060f, 0.056f, 0.048f };
        for (int f = 0; f < 4; f++)
        {
            var finger = new MeshInstance3D
            {
                Mesh = new CapsuleMesh { Radius = fingerR[f], Height = fingerLen[f], RadialSegments = 16, Rings = 6 },
                Position = new Vector3(-side * 0.011f, fingerY[f], -0.005f),
                RotationDegrees = new Vector3(0f, side * 16f, 90f),
                MaterialOverride = _gloveMat
            };
            hand.AddChild(finger);
            _gloveMeshes.Add(finger);
        }

        // Articulated 2-Segment Sculpted Thumb resting near DIFF/TORQ & top push-buttons
        var thumbBase = new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.0135f, Height = 0.044f, RadialSegments = 16, Rings = 6 },
            Position = new Vector3(-side * 0.014f, 0.030f, 0.018f),
            RotationDegrees = new Vector3(-16f, side * 22f, side * 48f),
            MaterialOverride = _gloveMat
        };
        hand.AddChild(thumbBase);
        _gloveMeshes.Add(thumbBase);

        var thumbTip = new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.0120f, Height = 0.036f, RadialSegments = 16, Rings = 6 },
            Position = new Vector3(-side * 0.032f, 0.043f, 0.022f),
            RotationDegrees = new Vector3(-22f, side * 32f, side * 66f),
            MaterialOverride = _gloveMat
        };
        hand.AddChild(thumbTip);
        _gloveMeshes.Add(thumbTip);

        // Exact Wrist Socket Anchor for DriverArmsIK3D (attached to the rotating glove!)
        var wristAnchor = new Node3D
        {
            Name = side < 0 ? "LeftWristAnchor" : "RightWristAnchor",
            Position = new Vector3(side * 0.006f, -0.042f, 0.010f)
        };
        hand.AddChild(wristAnchor);
        return wristAnchor;
    }

    public void UpdateColors(Color gloveColor)
    {
        _gloveMat = ProceduralMaterialFactory.CreateNomexFabricMaterial(gloveColor, false, null, false);
        for (int i = 0; i < _gloveMeshes.Count; i++)
        {
            _gloveMeshes[i].MaterialOverride = _gloveMat;
        }
    }

    public void UpdateTelemetry(
        float dt,
        float speedKmh,
        int gear,
        int position,
        float rpmNorm,
        float lapTime,
        float bestLap,
        float ersCharge,
        bool ersActive,
        bool offTrack,
        float tireHeat,
        float totalTime)
    {
        if (gear != _prevGear && speedKmh > 25f)
        {
            _shiftWasUp = gear > _prevGear;
            _shiftKickTimer = 0.15f;
            _prevGear = gear;
        }
        if (_shiftKickTimer > 0f) _shiftKickTimer = Mathf.Max(0f, _shiftKickTimer - dt);

        float kick = _shiftKickTimer > 0f ? Mathf.Sin((_shiftKickTimer / 0.15f) * Mathf.Pi) * 14f : 0f;
        _paddleLeft.RotationDegrees = new Vector3(0f, !_shiftWasUp ? kick : 0f, 0f);
        _paddleRight.RotationDegrees = new Vector3(0f, _shiftWasUp ? -kick : 0f, 0f);

        bool redlineFlash = rpmNorm > 0.93f && (((int)(totalTime * 16f) % 2) == 0);
        for (int i = 0; i < ShiftLedCount; i++)
        {
            bool lit = redlineFlash || ((i / (float)ShiftLedCount) < rpmNorm && speedKmh > 5f);
            Color c = i < 5 ? new Color(0.05f, 0.95f, 0.42f) : (i < 10 ? new Color(1.0f, 0.12f, 0.16f) : new Color(0.18f, 0.52f, 1.0f));
            _rpmLedMats[i].AlbedoColor = lit ? c : new Color(0.10f, 0.12f, 0.16f);
            _rpmLedMats[i].Emission = lit ? c : Colors.Black;
        }

        Color flagCol = offTrack
            ? new Color(1.0f, 0.72f, 0.0f)
            : (ersActive ? new Color(0.0f, 0.92f, 1.0f) : new Color(0.05f, 0.85f, 0.42f));
        bool flagLit = offTrack || ersActive || speedKmh > 40f;
        for (int i = 0; i < _flagLedMats.Length; i++)
        {
            _flagLedMats[i].AlbedoColor = flagLit ? flagCol : new Color(0.10f, 0.12f, 0.16f);
            _flagLedMats[i].Emission = flagLit ? flagCol : Colors.Black;
        }

        _mfdKph.Text = $"{(int)speedKmh}";
        _mfdLap.Text = lapTime < 60f
            ? $"{lapTime:00.000}"
            : $"{(int)(lapTime / 60f)}:{(lapTime % 60f):00.00}";
        _mfdPos.Text = $"P{position}";
        _mfdGear.Text = $"{gear}";
        _mfdGear.AddThemeColorOverride("font_color", redlineFlash ? new Color(0.45f, 0.88f, 1.0f) : Colors.White);

        if (bestLap < 900f)
        {
            float d = lapTime - bestLap;
            _mfdDelta.Text = d >= 0f ? $"+{d:0.00}" : $"{d:0.00}";
            _mfdDelta.AddThemeColorOverride("font_color", d <= 0f ? new Color(0.15f, 0.96f, 0.48f) : new Color(1.0f, 0.36f, 0.30f));
        }
        else
        {
            _mfdDelta.Text = "LIVE";
        }

        int fTemp = Mathf.RoundToInt(84f + tireHeat * 22f);
        int rTemp = Mathf.RoundToInt(87f + tireHeat * 20f);
        Color tCol = tireHeat > 0.75f ? new Color(1.0f, 0.78f, 0.32f) : new Color(0.90f, 0.97f, 0.92f);
        _mfdTempFL.Text = $"{fTemp}°C";
        _mfdTempFR.Text = $"{fTemp}°C";
        _mfdTempRL.Text = $"{rTemp}°C";
        _mfdTempRR.Text = $"{rTemp}°C";
        _mfdTempFL.AddThemeColorOverride("font_color", tCol);
        _mfdTempFR.AddThemeColorOverride("font_color", tCol);
        _mfdTempRL.AddThemeColorOverride("font_color", tCol);
        _mfdTempRR.AddThemeColorOverride("font_color", tCol);

        float frac = Mathf.Clamp(ersCharge / 100f, 0f, 1f);
        float totalW = 976f * frac;
        if (ersActive)
        {
            _ovtZoneRed.Visible = false;
            _ovtZoneYellow.Visible = false;
            _ovtZoneGreen.Visible = false;
            _ovtZoneCyan.Visible = true;
            _ovtZoneCyan.Size = new Vector2(Mathf.Max(8f, totalW), 124f);
        }
        else
        {
            _ovtZoneCyan.Visible = false;
            float w1 = Mathf.Min(totalW, 196f);
            float w2 = Mathf.Max(0f, Mathf.Min(totalW, 756f) - 196f);
            float w3 = Mathf.Max(0f, totalW - 756f);
            _ovtZoneRed.Visible = w1 > 2f;
            _ovtZoneYellow.Visible = w2 > 2f;
            _ovtZoneGreen.Visible = w3 > 2f;
            _ovtZoneRed.Size = new Vector2(w1, 124f);
            _ovtZoneYellow.Size = new Vector2(w2, 124f);
            _ovtZoneGreen.Size = new Vector2(w3, 124f);
        }

        _mfdOvtText.Text = offTrack
            ? "TRACK LIMITS"
            : (ersActive ? $"OVERTAKE ON  {(int)ersCharge}%" : $"OVERTAKE  {(int)ersCharge}%");
        _mfdOvtText.AddThemeColorOverride("font_color", frac > 0.24f ? new Color(0.04f, 0.06f, 0.10f) : Colors.White);
    }
}

