using Godot;
using System.Collections.Generic;

namespace ApexGP24;

public static class AssetLoader3D
{
    public static List<string> LoadedExternalAssets { get; } = new();

    public static void ResetLog()
    {
        LoadedExternalAssets.Clear();
    }

    public static string FindExistingPath(params string[] paths)
    {
        foreach (string p in paths)
        {
            if (ResourceLoader.Exists(p))
            {
                return p;
            }
        }
        return null;
    }

    public static Texture2D TryLoadTexture(string tag, params string[] paths)
    {
        string found = FindExistingPath(paths);
        if (found == null) return null;

        Texture2D tex = GD.Load<Texture2D>(found);
        if (tex != null && !LoadedExternalAssets.Contains(tag))
        {
            LoadedExternalAssets.Add(tag);
        }
        return tex;
    }

    /// <summary>
    /// Instantiates a user-uploaded .glb/.gltf model if present in res://assets/models/,
    /// automatically normalizing its scale & centering it to match real F1 dimensions!
    /// </summary>
    public static Node3D TryInstantiateGlb(string tag, float targetLengthOrWidth, bool alignBottomToZero, params string[] paths)
    {
        string found = FindExistingPath(paths);
        if (found == null) return null;

        PackedScene packed = GD.Load<PackedScene>(found);
        if (packed == null) return null;

        Node inst = packed.Instantiate();
        if (inst is not Node3D modelRoot)
        {
            inst?.QueueFree();
            return null;
        }

        var container = new Node3D { Name = $"CustomGlb_{tag}" };
        container.AddChild(modelRoot);

        if (TryComputeHierarchyAabb(modelRoot, Transform3D.Identity, out Aabb bounds))
        {
            float maxExtent = Mathf.Max(bounds.Size.X, Mathf.Max(bounds.Size.Y, bounds.Size.Z));
            if (maxExtent > 0.0001f)
            {
                float scaleFactor = targetLengthOrWidth / maxExtent;
                modelRoot.Scale = new Vector3(scaleFactor, scaleFactor, scaleFactor);

                Vector3 center = bounds.Position + bounds.Size * 0.5f;
                float offsetY = alignBottomToZero ? -bounds.Position.Y : -center.Y;
                modelRoot.Position = new Vector3(-center.X * scaleFactor, offsetY * scaleFactor, -center.Z * scaleFactor);
            }
        }

        if (!LoadedExternalAssets.Contains(tag))
        {
            LoadedExternalAssets.Add(tag);
        }
        return container;
    }

    private static bool TryComputeHierarchyAabb(Node node, Transform3D parentTransform, out Aabb combined)
    {
        combined = new Aabb();
        bool hasAny = false;

        Transform3D currentTransform = parentTransform;
        if (node is Node3D n3)
        {
            currentTransform = parentTransform * n3.Transform;
        }

        if (node is VisualInstance3D vis)
        {
            Aabb localBox = vis.GetAabb();
            if (localBox.Size.LengthSquared() > 0.000001f)
            {
                for (int i = 0; i < 8; i++)
                {
                    Vector3 corner = currentTransform * localBox.GetEndpoint(i);
                    if (!hasAny)
                    {
                        combined = new Aabb(corner, Vector3.Zero);
                        hasAny = true;
                    }
                    else
                    {
                        combined = combined.Expand(corner);
                    }
                }
            }
        }

        foreach (Node child in node.GetChildren())
        {
            if (TryComputeHierarchyAabb(child, currentTransform, out Aabb childBox))
            {
                if (!hasAny)
                {
                    combined = childBox;
                    hasAny = true;
                }
                else
                {
                    combined = combined.Merge(childBox);
                }
            }
        }

        return hasAny;
    }
}

