using Godot;
using System;

namespace ApexGP24;

public partial class F1AudioSynth : Node
{
    private const float SampleRate = 22050f;
    private AudioStreamPlayer _player;
    private AudioStreamGeneratorPlayback _playback;

    public bool Enabled { get; set; } = true;

    private float _rpm = 4200f;
    private float _speedKmh = 0f;
    private bool _throttle = false;
    private bool _brake = false;
    private bool _ers = false;
    private bool _onKerb = false;
    private bool _offTrack = false;

    private float _phase1 = 0f;
    private float _phase2 = 0f;
    private float _phase3 = 0f;
    private float _turboPhase = 0f;
    private float _kerbPhase = 0f;
    private float _shiftPopTimer = 0f;
    private int _prevGear = 1;
    private readonly Random _rng = new(1337);

    public override void _Ready()
    {
        var gen = new AudioStreamGenerator
        {
            MixRate = SampleRate,
            BufferLength = 0.08f
        };
        _player = new AudioStreamPlayer
        {
            Stream = gen,
            VolumeDb = -7.5f
        };
        AddChild(_player);
        _player.Play();
        _playback = _player.GetStreamPlayback() as AudioStreamGeneratorPlayback;
    }

    public void UpdateState(float rpm, float speedKmh, int gear, bool throttle, bool brake, bool ers, bool onKerb, bool offTrack)
    {
        if (gear != _prevGear && speedKmh > 30f)
        {
            _shiftPopTimer = 0.075f;
            _prevGear = gear;
        }
        _rpm = Mathf.Clamp(rpm, 3600f, 14500f);
        _speedKmh = speedKmh;
        _throttle = throttle;
        _brake = brake;
        _ers = ers;
        _onKerb = onKerb;
        _offTrack = offTrack;
    }

    public override void _Process(double delta)
    {
        if (_playback == null)
        {
            _playback = _player?.GetStreamPlayback() as AudioStreamGeneratorPlayback;
            if (_playback == null) return;
        }

        int frames = _playback.GetFramesAvailable();
        if (frames <= 0) return;

        if (!Enabled)
        {
            for (int i = 0; i < frames; i++)
            {
                _playback.PushFrame(Vector2.Zero);
            }
            return;
        }

        // V6 4-stroke firing frequency: 3 ignitions per rev -> rpm / 20 Hz!
        float fBase = _rpm / 20.0f;
        float inc1 = (fBase / SampleRate) * Mathf.Tau;
        float inc2 = (fBase * 1.5f / SampleRate) * Mathf.Tau;
        float inc3 = (fBase * 2.0f / SampleRate) * Mathf.Tau;
        float incTurbo = ((820f + (_rpm - 4000f) * 0.24f) / SampleRate) * Mathf.Tau;
        float incKerb = ((28f + _speedKmh * 0.22f) / SampleRate) * Mathf.Tau;

        float loadGain = _throttle ? 0.28f : (_brake ? 0.16f : 0.13f);
        float turboGain = (_throttle ? 0.045f : 0.015f) + (_ers ? 0.040f : 0f);
        float windGain = Mathf.Clamp(_speedKmh / 350f, 0f, 1f) * 0.055f;

        for (int i = 0; i < frames; i++)
        {
            _phase1 += inc1;
            _phase2 += inc2;
            _phase3 += inc3;
            _turboPhase += incTurbo;
            _kerbPhase += incKerb;

            if (_phase1 > Mathf.Tau) _phase1 -= Mathf.Tau;
            if (_phase2 > Mathf.Tau) _phase2 -= Mathf.Tau;
            if (_phase3 > Mathf.Tau) _phase3 -= Mathf.Tau;
            if (_turboPhase > Mathf.Tau) _turboPhase -= Mathf.Tau;
            if (_kerbPhase > Mathf.Tau) _kerbPhase -= Mathf.Tau;

            // Rich soft-clipped F1 V6 exhaust wave
            float rawEng =
                Mathf.Sin(_phase1) * 0.55f +
                Mathf.Sin(_phase2) * 0.30f +
                Mathf.Sin(_phase3) * 0.24f;
            float eng = Mathf.Tanh(rawEng * (_throttle ? 2.1f : 1.3f)) * loadGain;

            // Turbo / MGU-K electric whine
            float turbo = Mathf.Sin(_turboPhase) * turboGain;

            // Subtle aerodynamic rush & gravel/kerb texture
            float noise = ((float)_rng.NextDouble() * 2.0f - 1.0f);
            float aero = noise * windGain;
            float surface = 0f;
            if (_onKerb && _speedKmh > 25f)
            {
                surface = Mathf.Sin(_kerbPhase) * 0.11f;
            }
            else if (_offTrack && _speedKmh > 20f)
            {
                surface = noise * 0.09f;
            }

            // Crisp gear-shift exhaust crackle/cut
            float pop = 0f;
            if (_shiftPopTimer > 0f)
            {
                _shiftPopTimer -= 1.0f / SampleRate;
                eng *= 0.45f;
                pop = noise * 0.14f;
            }

            float sample = Mathf.Clamp(eng + turbo + aero + surface + pop, -0.85f, 0.85f);
            _playback.PushFrame(new Vector2(sample, sample));
        }
    }
}

