                spin.AddChild(new MeshInstance3D { Mesh = isRear ? _sharedRearTireMesh : _sharedFrontTireMesh, MaterialOverride = _sharedRubberMat });
                spin.AddChild(new MeshInstance3D { Mesh = isRear ? _sharedRearDiscOut : _sharedFrontDiscOut, MaterialOverride = sidewallMat });
                spin.AddChild(new MeshInstance3D { Mesh = isRear ? _sharedRearDiscIn : _sharedFrontDiscIn, MaterialOverride = sidewallMat });
