using Godot;

namespace ApexGP24;

public static class GameSettings
{
    private const string SettingsPath = "user://apex_gp_settings.cfg";

    public static bool AnalogSteering { get; set; } = false;
    public static int SensitivityIndex { get; set; } = 2; // 0=Suave, 1=Media, 2=Ágil, 3=Pro
    public static bool RacingLineOn { get; set; } = true;
    public static bool SoundOn { get; set; } = true;
    public static int LiveryIndex { get; set; } = 0;
    public static int TimeOfDayIndex { get; set; } = 0; // 0=Día, 1=Tarde, 2=Noche
    public static bool HighQuality { get; set; } = true;
    public static bool CockpitCamera { get; set; } = true;

    public static void Load()
    {
        var cfg = new ConfigFile();
        if (cfg.Load(SettingsPath) != Error.Ok)
        {
            return;
        }

        AnalogSteering = cfg.GetValue("controls", "analog_steering", false).AsBool();
        SensitivityIndex = Mathf.Clamp(cfg.GetValue("controls", "sensitivity_index", 2).AsInt32(), 0, 3);
        RacingLineOn = cfg.GetValue("assists", "racing_line", true).AsBool();
        SoundOn = cfg.GetValue("audio", "sound_v6", true).AsBool();
        LiveryIndex = Mathf.Clamp(cfg.GetValue("car", "livery_index", 0).AsInt32(), 0, PlayerCar3D.Liveries.Length - 1);
        CockpitCamera = cfg.GetValue("car", "cockpit_camera", true).AsBool();
        TimeOfDayIndex = Mathf.Clamp(cfg.GetValue("graphics", "time_of_day", 0).AsInt32(), 0, 2);
        HighQuality = cfg.GetValue("graphics", "high_quality", true).AsBool();
    }

    public static void Save()
    {
        var cfg = new ConfigFile();
        cfg.SetValue("controls", "analog_steering", AnalogSteering);
        cfg.SetValue("controls", "sensitivity_index", SensitivityIndex);
        cfg.SetValue("assists", "racing_line", RacingLineOn);
        cfg.SetValue("audio", "sound_v6", SoundOn);
        cfg.SetValue("car", "livery_index", LiveryIndex);
        cfg.SetValue("car", "cockpit_camera", CockpitCamera);
        cfg.SetValue("graphics", "time_of_day", TimeOfDayIndex);
        cfg.SetValue("graphics", "high_quality", HighQuality);
        cfg.Save(SettingsPath);
    }
}
